Integer add_clamped(Integer value, Integer delta, Integer minimum, Integer maximum)
{
    // Python版は上限のない整数を加算してから numwrap を行う。
    // 各呼び出し元の範囲を保ちつつ、中間の加算のオーバーフローを避ける。
    if (delta > 0 && value > std::numeric_limits<Integer>::max() - delta) return maximum;
    if (delta < 0 && value < std::numeric_limits<Integer>::min() - delta) return minimum;
    return std::clamp<Integer>(value + delta, minimum, maximum);
}

