Real parse_bounded_real(const String& text, Real minimum, Real maximum, Real fallback)
{
    try {
        std::size_t used = 0;
        const Real value = std::stod(text, &used);
        if (used != text.size() || !std::isfinite(value)) return fallback;
        return std::clamp(value, minimum, maximum);
    } catch (...) {
        return fallback;
    }
}

std::optional<Integer> real_to_integer(Real value)
{
    if (!std::isfinite(value)) return std::nullopt;
    constexpr Real minimum = static_cast<Real>(std::numeric_limits<Integer>::lowest());
    constexpr Real maximum_exclusive = -minimum;
    if (value < minimum || value >= maximum_exclusive) return std::nullopt;
    return static_cast<Integer>(value);
}

Integer python3_round(Real value)
{
    if (!std::isfinite(value)) throw std::invalid_argument("cannot round a non-finite life value");
    const Real lower = std::floor(value);
    const Real fraction = value - lower;
    Real rounded = lower;
    if (fraction > 0.5) {
        rounded = lower + 1.0;
    } else if (fraction == 0.5) {
        const Real parity = std::fmod(std::fabs(lower), 2.0);
        rounded = parity == 0.0 ? lower : lower + 1.0;
    }
    return real_to_integer(rounded).value_or(0);
}

