std::shared_ptr<::cw::character::Character> borrowed_character(Character* character)
{
    if (!character) return {};
    // 実行中のキャラクターは PlayerCard/EnemyCard/FriendCard の shared_ptr
    // が所有する。 CardHeader がPython相当の弱い所有者参照を保存するときも、同じ
    // 制御ブロックを使う。 何もしない解放関数の一時 shared_ptr では initialize()
    // 後に失効し、 XMLから読んだスキル・アイテム・召喚獣の所有者がすべて消えてしまう。
    if (auto owned = character->weak_from_this().lock()) return owned;
    // 独立した値形式のテストには、スタック上のCharacterを使うものがあ
    // る。 呼び出し中だけの非所有の変換は維持するが、保存する弱参照を支えら
    // れるものとは扱わない。 製品のキャラクターは上の所有される経路を使う。
    return std::shared_ptr<::cw::character::Character>(character, [](Character*) {});
}

// Python版の反転属性は一つだが、C++のカードキャラクターは二つの基底を
// 持つ。 共通のアニメーション・カード処理が画像を選ぶ前に、両方を復元する。
void set_coupon_reverse_state(Character& character, bool reversed, bool update, bool force_state = true)
{
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(borrowed_character(&character));
    if (card) card->m_reversed = character.m_reversed;
    if (update && character.m_reversed != reversed) {
        if (!card || card->m_status == "hidden") character.reverse();
        else ::cw::animation::animate_sprite(card, "reverse", true, false, false, false);
    }
    // Python版の _set/_remove はアニメーション後にフラグを強
    // 制する。 一括置換では、中断・停止も含めてアニメーションの結果を保持する。
    if (!force_state) reversed = card ? card->m_reversed : character.m_reversed;
    character.m_reversed = reversed;
    if (card) card->m_reversed = reversed;
}

