void sync_cardpocket_value(Character& character)
{
    auto all = std::make_shared<::cw::data::VariantSequence>();
    const auto append_pocket = [&all](const auto& pocket) {
        auto sequence = std::make_shared<::cw::data::VariantSequence>();
        for (const auto& header : pocket) {
            if (header) sequence->m_values.emplace_back(::cw::lib::Value(
                std::static_pointer_cast<::cw::lib::Object>(header)));
        }
        all->m_values.emplace_back(::cw::lib::Value(
            std::static_pointer_cast<::cw::lib::Object>(sequence)));
    };
    append_pocket(std::get<0>(character.m_cardpocket_typed));
    append_pocket(std::get<1>(character.m_cardpocket_typed));
    append_pocket(std::get<2>(character.m_cardpocket_typed));
    character.m_cardpocket = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(all));
}

