void collect_target_values(const ::cw::lib::Value& value,
                           std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>& targets)
{
    if (const auto card = value_card(value)) {
        targets.push_back(card);
        return;
    }
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
    if (!object || !*object) return;
    const auto sequence = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object);
    if (!sequence) return;
    for (const auto& item : sequence->m_values) collect_target_values(item, targets);
}

std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> value_targets(const ::cw::lib::Value& value)
{
    std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> result;
    collect_target_values(value, result);
    return result;
}

::cw::lib::Value targets_value(const std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>& targets)
{
    auto sequence = std::make_shared<::cw::data::VariantSequence>();
    for (const auto& target : targets) {
        if (target) sequence->m_values.emplace_back(std::static_pointer_cast<::cw::lib::Object>(target));
    }
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sequence));
}

bool has_target_value(const ::cw::lib::Value& value)
{
    if (value.is_none()) return false;
    if (value_card(value)) return true;
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
    return (object && *object && std::dynamic_pointer_cast<Character>(*object) != nullptr) || !value_targets(value).empty();
}

