std::shared_ptr<::cw::sprite::card::CWPyCard> choose_card(
    const std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>& cards)
{
    if (cards.empty()) return nullptr;
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_dice) return cards.front();
    std::vector<::cw::lib::Value> values;
    values.reserve(cards.size());
    for (const auto& card : cards) values.emplace_back(std::static_pointer_cast<::cw::lib::Object>(card));
    return value_card(::cw::g_cwpy->m_dice->choice_exists(std::move(values)));
}

