std::vector<String> value_strings(const ::cw::lib::Value& value)
{
    std::vector<String> result;
    for (const auto& item : value_sequence(value)) {
        if (const auto* text = std::get_if<String>(&item.storage())) result.push_back(*text);
        else {
            for (const auto& nested : value_strings(item)) result.push_back(nested);
        }
    }
    return result;
}

