std::shared_ptr<Element> ensure_coupons_element(Character& character)
{
    if (!character.m_data_typed) return nullptr;
    if (const auto coupons = character.m_data_typed->find("Property/Coupons"); coupons && *coupons) return *coupons;
    auto property = character.m_data_typed->find("Property");
    if (!property || !*property) return nullptr;
    auto coupons = ::cw::data::make_element("Coupons");
    (*property)->append(coupons);
    return coupons;
}

void remove_card_from_pocket_xml(Character& character, Integer pocket_index,
                                 const std::shared_ptr<::cw::header::CardHeader>& header)
{
    if (!character.m_data_typed || !header) return;
    const String path = pocket_index == 0 ? "SkillCards" : (pocket_index == 1 ? "ItemCards" : "BeastCards");
    const auto group = character.m_data_typed->find(path);
    if (!group || !*group) return;
    const auto card_element = value_element(header->m_carddata);
    for (const auto& child : (*group)->m_children) {
        if (child && ((card_element && child == card_element) || child->get("id", "") == std::to_string(header->m_id))) {
            (*group)->remove(child);
            mark_edited(character);
            return;
        }
    }
}

void edit_character_xml(Character& character, const String& path, const String& value,
                         const std::optional<String>& attribute = std::nullopt)
{
    if (!character.m_data_typed) return;
    character.m_data_typed->edit(path, value, attribute);
    mark_edited(character);
}

bool value_bool(const ::cw::lib::Value& value)
{
    if (const auto* real = std::get_if<Real>(&value.storage())) {
        // ネイティブのコールバックからNaN・無限大が来ても、未検査の状態遷移にしない
        // 。 Decimalは Value::as_bool() を通して正確に扱う。
        return std::isfinite(*real) && *real != 0.0;
    }
    if (const auto* decimal = std::get_if<Decimal>(&value.storage())) return !decimal->is_zero();
    return value.as_bool();
}

std::optional<Decimal> value_decimal(const ::cw::lib::Value& value)
{
    if (const auto* decimal = std::get_if<Decimal>(&value.storage())) return *decimal;
    if (const auto* integer = std::get_if<Integer>(&value.storage())) return Decimal(*integer);
    if (const auto* flag = std::get_if<bool>(&value.storage())) return Decimal(*flag ? 1 : 0);
    if (const auto* real = std::get_if<Real>(&value.storage())) {
        if (!std::isfinite(*real)) return std::nullopt;
        std::ostringstream out;
        out << std::setprecision(std::numeric_limits<Real>::max_digits10) << *real;
        try { return Decimal::parse(out.str()); } catch (const ::cw::lib::DecimalError&) { return std::nullopt; }
    }
    if (const auto* text = std::get_if<String>(&value.storage())) {
        try { return Decimal::parse(*text); } catch (const ::cw::lib::DecimalError&) { return std::nullopt; }
    }
    return std::nullopt;
}
