void Character::add_deck_registration(::cw::lib::String arg_name, std::vector<std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::String, ::cw::lib::String, std::optional<::cw::lib::String>, std::optional<::cw::lib::String>>> arg_items, std::optional<::cw::lib::String> arg_rtype, std::optional<::cw::lib::String> arg_scenario, std::optional<::cw::lib::String> arg_author)
{
    mark_yado_changed();
    if (!m_data_typed) return;
    auto root = m_data_typed->getroot();
    if (!root) throw std::logic_error("Character::add_deck_registration XML has no root");
    auto regs = root->find("DeckRegistrations");
    auto registrations = regs && *regs ? *regs : ::cw::data::make_element("DeckRegistrations");
    if (!(regs && *regs)) root->append(registrations);

    const auto inferred_type = arg_items.empty() ? String{} : std::get<2>(arg_items.front());
    const auto type = arg_rtype.value_or(inferred_type);
    auto registration = ::cw::data::make_element("Registration");
    if (!type.empty()) registration->set("type", type);
    registration->append(::cw::data::make_element("Name", arg_name));
    if (arg_scenario && !arg_scenario->empty()) registration->append(::cw::data::make_element("ScenarioName", *arg_scenario));
    if (arg_author && !arg_author->empty()) registration->append(::cw::data::make_element("Author", *arg_author));
    for (const auto& item : arg_items) {
        std::map<String, String> attributes{{"name", std::get<0>(item)}};
        if (!std::get<1>(item).empty()) attributes["desc"] = std::get<1>(item);
        if (!std::get<2>(item).empty()) attributes["type"] = std::get<2>(item);
        if (!std::get<3>(item).empty()) attributes["scenario"] = std::get<3>(item);
        if (std::get<4>(item) && !std::get<4>(item)->empty()) attributes["author"] = *std::get<4>(item);
        if (std::get<5>(item) && !std::get<5>(item)->empty()) attributes["personal"] = *std::get<5>(item);
        registration->append(::cw::data::make_element("Item", {}, attributes));
    }
    // Python版と同様、タグにかかわらず全子を調べ、
    // Name要素がない・空の場合はname属性を使う。
    for (const auto& old : std::vector<std::shared_ptr<Element>>(registrations->m_children)) {
        if (!old) continue;
        const auto name_element = old->find("Name");
        const auto old_name = name_element && *name_element && !(*name_element)->m_text.empty() ? (*name_element)->m_text : old->get("name", "");
        if (old_name == arg_name && old->get("type", "") == type) registrations->remove(old);
    }
    registrations->append(registration);
    mark_edited(*this);
    // C++版の型付き表示キャッシュも、同じXML走
    // 査から更新する。 二つ目の登録方針を持たない。
    (void)get_deck_registrations();
}

void Character::remove_deck_registration(::cw::lib::String arg_name, std::optional<::cw::lib::String> arg_rtype)
{
    mark_yado_changed();
    if (!m_data_typed) return;
    const auto root = m_data_typed->getroot();
    const auto regs = root ? root->find("DeckRegistrations") : std::nullopt;
    if (!regs || !*regs) return;
    const auto type = arg_rtype.value_or(String{});
    bool removed = false;
    for (const auto& registration : std::vector<std::shared_ptr<Element>>((*regs)->m_children)) {
        if (!registration) continue;
        const auto name = registration->find("Name");
        const auto registration_name = name && *name && !(*name)->m_text.empty() ? (*name)->m_text : registration->get("name", "");
        if (registration_name == arg_name && registration->get("type", "") == type) {
            (*regs)->remove(registration);
            removed = true;
        }
    }
    if (removed) { mark_edited(*this); (void)get_deck_registrations(); }
}

bool Character::rename_deck_registration(::cw::lib::String arg_name, ::cw::lib::String arg_new_name, std::optional<::cw::lib::String> arg_rtype)
{
    mark_yado_changed();
    if (!m_data_typed) return false;
    const auto root = m_data_typed->getroot();
    const auto regs = root ? root->find("DeckRegistrations") : std::nullopt;
    if (!regs || !*regs) return false;
    const auto type = arg_rtype.value_or(String{});
    bool renamed = false;
    for (const auto& registration : (*regs)->m_children) {
        if (!registration) continue;
        const auto name = registration->find("Name");
        const auto registration_name = name && *name && !(*name)->m_text.empty() ? (*name)->m_text : registration->get("name", "");
        if (registration_name == arg_name && registration->get("type", "") == type) {
            if (name && *name) (*name)->set_text(arg_new_name);
            else registration->set("name", arg_new_name);
            renamed = true;
        }
    }
    if (renamed) { mark_edited(*this); (void)get_deck_registrations(); }
    return renamed;
}

std::vector<std::map<::cw::lib::String, ::cw::lib::Value>> Character::get_deck_registrations()
{
    std::vector<std::map<String, ::cw::lib::Value>> result;
    m_deck_registrations_typed.clear();
    if (!m_data_typed || !m_data_typed->getroot()) return result;
    const auto regs = m_data_typed->getroot()->find("DeckRegistrations");
    if (!regs || !*regs) return result;
    for (const auto& registration : (*regs)->m_children) {
        if (!registration) continue;
        DeckRegistration typed;
        const auto name = registration->find("Name");
        typed.name = name && *name && !(*name)->m_text.empty() ? (*name)->m_text : registration->get("name", "");
        typed.type = registration->get("type", "");
        const auto scenario = registration->find("ScenarioName");
        typed.scenario = scenario && *scenario && !(*scenario)->m_text.empty() ? (*scenario)->m_text : registration->get("scenario", "");
        const auto author = registration->find("Author");
        typed.author = author && *author && !(*author)->m_text.empty() ? (*author)->m_text : registration->get("author", "");
        std::map<String, ::cw::lib::Value> view{
            {"name", typed.name}, {"type", typed.type}, {"scenario", typed.scenario}, {"author", typed.author}};
        for (const auto& item : registration->iter(std::optional<String>("Item"))) {
            if (!item || item->m_tag != "Item") continue;
            DeckRegistrationItem typed_item;
            typed_item.name = item->get("name", "");
            if (typed_item.name.empty()) typed_item.name = item->m_text;
            typed_item.desc = item->get("desc", "");
            typed_item.type = item->get("type", "");
            typed_item.scenario = item->get("scenario", "");
            typed_item.author = item->get("author", "");
            typed_item.personal = item->get("personal", "");
            typed.items.push_back(typed_item);
        }
        // VariantSequenceをネストして、Value境界でもPythonのitems列
        // (name, desc, type, scenario, author, personal)を失わないようにする。
        auto items = std::make_shared<::cw::data::VariantSequence>();
        for (const auto& typed_item : typed.items) {
            auto item = std::make_shared<::cw::data::VariantSequence>();
            item->m_values.emplace_back(typed_item.name);
            item->m_values.emplace_back(typed_item.desc);
            item->m_values.emplace_back(typed_item.type);
            item->m_values.emplace_back(typed_item.scenario);
            item->m_values.emplace_back(typed_item.author);
            item->m_values.emplace_back(typed_item.personal);
            items->m_values.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(item)));
        }
        view["items"] = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(items));
        m_deck_registrations_typed.push_back(typed);
        result.push_back(std::move(view));
    }
    return result;
}

std::tuple<std::vector<std::shared_ptr<::cw::header::CardHeader>>, std::vector<std::shared_ptr<::cw::header::CardHeader>>, std::vector<std::shared_ptr<::cw::header::CardHeader>>> Character::load_cardpocket_from_xml()
{
    if (!m_data_typed || !m_data_typed->getroot()) return {};
    const bool from_scenario = m_data_typed->getroot()->m_tag == "CastCard";
    const auto maxnums = get_cardpocketspace();
    // 宿の容量への意図的な拡張として、獲得後に宿の上限が無効化・縮小
    // されても、保存済みPCのスキルを捨てない。 獲得時は引き続き
    // get_cardpocketspace() を使う。 NPC
    // ・アイテム・召喚獣の上限は、既存の読み込み動作を維持する。
    const auto load_skill_max = dynamic_cast<Player*>(this)
        ? std::max<Integer>(50, std::get<0>(maxnums)) : std::get<0>(maxnums);
    const std::array<String, 3> paths{"SkillCards", "ItemCards", "BeastCards"};
    auto result = std::make_tuple(std::vector<std::shared_ptr<::cw::header::CardHeader>>{},
                                  std::vector<std::shared_ptr<::cw::header::CardHeader>>{},
                                  std::vector<std::shared_ptr<::cw::header::CardHeader>>{});
    for (std::size_t index = 0; index < paths.size(); ++index) {
        const auto pocket_element = m_data_typed->find(paths[index]);
        if (!pocket_element || !*pocket_element) continue;
        auto& headers = index == 0 ? std::get<0>(result) : (index == 1 ? std::get<1>(result) : std::get<2>(result));
        for (const auto& link : (*pocket_element)->m_children) {
            if (static_cast<Integer>(headers.size()) >= load_skill_max && index == 0) break;
            if (static_cast<Integer>(headers.size()) >= std::get<1>(maxnums) && index == 1) break;
            if (static_cast<Integer>(headers.size()) >= std::get<2>(maxnums) && index == 2) break;
            const auto carddata = resolve_carddata(link, from_scenario, std::nullopt);
            if (!carddata || !*carddata) continue;
            auto header = std::make_shared<::cw::header::CardHeader>();
            header->initialize(std::nullopt, borrowed_character(this), *carddata, from_scenario,
                               {}, false, std::nullopt, std::nullopt, {}, {});
            headers.push_back(std::move(header));
        }
        // Python版の get_carddata() 後の
        // 削除・追加と同様、解決したリンクを正式な子とする。
        const auto original = (*pocket_element)->m_children;
        for (const auto& child : original) (*pocket_element)->remove(child);
        for (const auto& header : headers) {
            const auto element = header ? value_element(header->m_carddata) : nullptr;
            if (element) (*pocket_element)->append(element);
        }
    }
    return result;
}

void Character::replace_cardposition(::cw::lib::Integer arg_cardtype, std::shared_ptr<::cw::header::CardHeader> arg_header1, std::shared_ptr<::cw::header::CardHeader> arg_header2)
{
    const auto pocket_index = three_item_index(arg_cardtype);
    auto& pocket = pocket_index == 0 ? std::get<0>(m_cardpocket_typed) :
                   (pocket_index == 1 ? std::get<1>(m_cardpocket_typed) : std::get<2>(m_cardpocket_typed));
    const auto first = std::find(pocket.begin(), pocket.end(), arg_header1);
    const auto second = std::find(pocket.begin(), pocket.end(), arg_header2);
    if (first == pocket.end() || second == pocket.end()) throw std::out_of_range("card header not in pocket");
    const auto index1 = static_cast<std::size_t>(std::distance(pocket.begin(), first));
    const auto index2 = static_cast<std::size_t>(std::distance(pocket.begin(), second));
    std::swap(pocket[index1], pocket[index2]);
    sync_cardpocket_value(*this);
    // Python版と同様、XMLコンテナーを選ぶ前にポケットを交換する。 生の
    // 負のcardtypeにはXMLの選択先がないため、その失敗順序を維持する。
    if (arg_cardtype < 0) throw std::invalid_argument("unbound card pocket XML container");
    if (!m_data_typed) throw std::invalid_argument("missing character XML tree");
    const auto path = arg_cardtype == 0 ? String("SkillCards") : (arg_cardtype == 1 ? String("ItemCards") : String("BeastCards"));
    const auto element = m_data_typed->find(path);
    if (!element || !*element) return;
    if (index1 >= (*element)->m_children.size() || index2 >= (*element)->m_children.size())
        throw std::out_of_range("card pocket XML child index");
    std::swap((*element)->m_children[index1], (*element)->m_children[index2]);
    mark_edited(*this);
}

std::set<::cw::lib::String> Character::get_keycodes(bool arg_skill, bool arg_item, bool arg_beast)
{
    std::set<String> result;
    const auto add = [&result](const auto& pocket) {
        for (const auto& header : pocket) {
            if (!header) continue;
            for (const auto& keycode : header->get_keycodes(true)) if (!keycode.empty()) result.insert(keycode);
        }
    };
    if (arg_skill) add(std::get<0>(m_cardpocket_typed));
    if (arg_item) add(std::get<1>(m_cardpocket_typed));
    if (arg_beast) add(std::get<2>(m_cardpocket_typed));
    return result;
}

std::optional<std::shared_ptr<::cw::header::CardHeader>> Character::find_keycode(::cw::lib::String arg_keycode, bool arg_skill, bool arg_item, bool arg_beast, bool arg_hand, ::cw::lib::String arg_condition)
{
    const auto matches = [&arg_keycode, &arg_condition](const std::shared_ptr<::cw::header::CardHeader>& header) {
        if (!header) return false;
        const auto keycodes = header->get_keycodes(true);
        const bool has = std::find(keycodes.begin(), keycodes.end(), arg_keycode) != keycodes.end();
        return arg_condition == "HasNot" ? !has : has;
    };
    if (arg_hand && m_deck) {
        for (const auto& header : m_deck->get_hand(borrowed_character(this))) if (matches(header)) return header;
        if (const auto* header = std::get_if<::cw::lib::ObjectPtr>(&std::get<1>(m_actiondata).storage()); header && *header) {
            if (const auto action_header = std::dynamic_pointer_cast<::cw::header::CardHeader>(*header); matches(action_header)) return action_header;
        }
        if (const auto used = m_deck->get_used(); used && *used && matches(*used)) return *used;
    }
    if (arg_skill) for (const auto& header : std::get<0>(m_cardpocket_typed)) if (matches(header)) return header;
    if (arg_item) for (const auto& header : std::get<1>(m_cardpocket_typed)) if (matches(header)) return header;
    if (arg_beast) for (const auto& header : std::get<2>(m_cardpocket_typed)) if (matches(header)) return header;
    return {};
}

