bool Character::is_effective(std::shared_ptr<::cw::header::CardHeader> arg_header, std::shared_ptr<::cw::data::CWPyElement> arg_motion)
{
    if (!is_card_character(*this)) throw std::logic_error("Character::is_effective requires a card character");
    if (is_reversed() || is_vanished() || (card_status(*this) == "hidden" && !dynamic_cast<Friend*>(this) && !dynamic_cast<Player*>(this))) return false;
    if (!arg_motion) return true;
    if (::cw::effectmotion::is_noeffect(arg_motion->get("element", ""), borrowed_character(this))) return false;
    const auto type = arg_motion->get("type", "");
    if (type == "Heal") return is_injuredall();
    if (type == "Damage" || type == "Absorb" || type == "Paralyze" || type == "Poison" ||
        type == "GetSkillPower" || type == "LoseSkillPower") return !is_unconscious();
    if (type == "DisParalyze") return is_paralyze();
    if (type == "DisPoison") return is_poison();
    // Python の `mtype in "Sleep"` という互換挙動（通常はSleep一致）を保持。
    if (String("Sleep").find(type) != String::npos) return !is_unconscious() && !is_sleep();
    if (type == "Confuse") return !is_unconscious() && !is_confuse();
    if (type == "Overheat") return !is_unconscious() && !is_overheat();
    if (type == "Brave") return !is_unconscious() && !is_brave();
    if (type == "Panic") return !is_unconscious() && !is_panic();
    if (type == "Normal") return !is_unconscious() && !is_normal();
    if (type == "Bind") return !is_unconscious() && !is_bind();
    if (type == "DisBind") return is_bind();
    if (type == "Silence") return !is_unconscious() && !is_silence();
    if (type == "DisSilence") return !is_unconscious() && is_silence();
    if (type == "FaceUp") return !is_unconscious() && !is_faceup();
    if (type == "FaceDown") return !is_unconscious() && is_faceup();
    if (type == "AntiMagic") return !is_unconscious() && !is_antimagic();
    if (type == "DisAntiMagic") return !is_unconscious() && is_antimagic();
    const auto enhancement_target = [&](Integer current, bool enhanced) {
        if (is_unconscious()) return false;
        const auto value = read_int(std::make_shared<Tree>(arg_motion), ".", std::optional<String>("value"), 0);
        const auto clamped = enhancement_value(current);
        if (value == 0) return enhanced;
        return value < 0 ? value < clamped : clamped < value;
    };
    if (type == "EnhanceAction") return enhancement_target(m_enhance_act, is_enhanced_act());
    if (type == "EnhanceAvoid") return enhancement_target(m_enhance_avo, is_enhanced_avo());
    if (type == "EnhanceResist") return enhancement_target(m_enhance_res, is_enhanced_res());
    if (type == "EnhanceDefense") return enhancement_target(m_enhance_def, is_enhanced_def());
    if (type == "VanishCard" || type == "DealAttackCard" || type == "DealPowerfulAttackCard" ||
        type == "DealCriticalAttackCard" || type == "DealFeintCard" || type == "DealDefenseCard" ||
        type == "DealDistanceCard" || type == "DealConfuseCard" || type == "DealSkillCard" ||
        type == "CancelAction") return is_active();
    if (type == "VanishBeast") return has_beast() > 0;
    if (type == "SummonBeast") {
        const auto beasts = arg_motion->find("Beasts");
        if (beasts && *beasts) {
            for (const auto& link : (*beasts)->m_children) {
                const auto carddata = resolve_carddata(link, true, arg_header);
                if (carddata && *carddata) {
                    if (can_addbeast(*carddata)) return true;
                }
            }
        }
        return false;
    }
    if (type == "NoEffect") return !is_unconscious();
    return true;
}

bool Character::use_card(::cw::lib::Value arg_targets, std::shared_ptr<::cw::header::CardHeader> arg_header)
{
    if (!is_card_character(*this)) {
        throw std::logic_error("Character::use_card requires a card character");
    }
    if (!arg_header) throw std::invalid_argument("Character::use_card requires card header");
    // Python版の単一イベントキューと異なり、ネイティブのアニメーション中に、
    // 失敗した使用も含めCardEvent開始前の別クリックが届く場合がある。
    // イベントスタックだけでなく、準備・全アニメーション・効果・後処理を保護する。
    struct CardUseInputGuard {
        std::shared_ptr<::cw::thread::CWPy> runtime;
        explicit CardUseInputGuard(std::shared_ptr<::cw::thread::CWPy> value)
            : runtime(std::move(value)) {
            if (runtime) ++runtime->m_card_use_depth;
        }
        ~CardUseInputGuard() {
            if (!runtime) return;
            if (runtime->m_card_use_depth == 1 && ::cw::g_cwpy == runtime) {
                // 通常のカードクリックを再開する前に、押下中・待機中の使用
                // 入力を消費する。 カード効果からの例外を置き換えない。
                try { runtime->cancel_modal_input_sequence(); } catch (...) {}
            }
            --runtime->m_card_use_depth;
        }
    } input_guard(::cw::g_cwpy);
    if (::cw::g_fsync) ::cw::g_fsync->sync();

    const auto self = borrowed_character(this);
    const auto self_card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(self);
    if (::cw::g_cwpy && ::cw::g_cwpy->m_advlog)
        ::cw::g_cwpy->m_advlog->use_card(self, arg_header, arg_targets);
    mark_yado_changed();
    const auto targets = value_targets(arg_targets);
    const auto data = value_element(arg_header->m_carddata);
    if (!data) throw std::logic_error("CardHeader.carddata is not an XML element");

    const auto soundpath = ::cw::util::validate_filepath(data->gettext("Property/SoundPath", ""));
    const auto volume = read_element_int(data, "Property/SoundPath", String("volume"), 100);
    const auto loopcount = read_element_int(data, "Property/SoundPath", String("loopcount"), 1);
    const auto channel = read_element_int(data, "Property/SoundPath", String("channel"), 0);
    const auto fade = read_element_int(data, "Property/SoundPath", String("fadein"), 0);
    const auto play_card_sound = [&] {
        if (::cw::g_cwpy && !soundpath.empty())
            ::cw::g_cwpy->play_sound_with(soundpath, arg_header, volume, loopcount, channel, fade);
    };
    const bool battle_speed = ::cw::g_cwpy && ::cw::g_cwpy->is_battlestatus();
    const auto animate = [battle_speed](const std::shared_ptr<::cw::sprite::base::CWPySprite>& sprite,
                                        const String& type) {
        if (sprite) ::cw::animation::animate_sprite(sprite, type, true, false, false, battle_speed);
    };
    if (::cw::g_cwpy) {
        ::cw::g_cwpy->clear_inusecardimg(std::nullopt);
        ::cw::g_cwpy->clear_targetarrow();
    }

    const auto level = arg_header->m_type == "SkillCard" ? read_element_int(data, "Property/Level", std::nullopt, 0) : 0;
    const auto spellcard = data->getbool("Property/EffectType", ::cw::lib::Value("spell"), false);
    const auto effecttype = data->gettext("Property/EffectType", "None");
    const auto magiccard = effecttype == "Magic" || effecttype == "PhysicalMagic";
    bool misfire = spellcard && (is_silence() || is_inactive());
    misfire = misfire || (magiccard && is_antimagic() && data->m_tag != "BeastCard");
    misfire |= (level > 0 && !decide_misfire(level)); // Python版と同様、前に不発となっていてもこの式を評価する。
    const auto fail_effect = [&](const std::shared_ptr<::cw::sprite::base::CWPySprite>& sprite) {
        if (!::cw::g_cwpy) return;
        ::cw::g_cwpy->play_sound(arg_header->m_type == "BeastCard" ? "error" : "confuse",
                                 true, 100, 1, 0, 0, false);
        animate(sprite, "axialvibe");
    };

    bool friend_displayed = false;
    if (::cw::g_cwpy && self_card) {
        const auto style = arg_header->get_showstyle();
        ::cw::g_cwpy->m_event->m_in_inusecardevent = true;
        if (style == "Invisible") {
            if (misfire) fail_effect(self_card);
        } else if (style == "Center") {
            ::cw::g_cwpy->set_inusecardimg(self_card, arg_header, "hidden", true, 255, true);
            const auto image = ::cw::g_cwpy->get_inusecardimg();
            if (image && *image) {
                animate(*image, "deal");
                play_card_sound();
                if (::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_enlarge_beastcardzoomingratio) {
                    animate(*image, "zoomin_slow");
                } else {
                    (*image)->m_zoomsize_noscale = {16, 22};
                    animate(*image, "zoomin");
                }
                if (::cw::g_cwpy->m_setting) {
                    const auto base = ::cw::g_cwpy->m_setting->get_dealspeed(battle_speed);
                    const auto wait = ::cw::g_cwpy->m_setting->m_wait_usecard ? base * 2 + 1 : base + 1;
                    ::cw::g_cwpy->wait_frame(wait, ::cw::g_cwpy->m_setting->m_can_skipanimation, std::nullopt, 0);
                }
                if (misfire) fail_effect(*image);
                animate(*image, ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_enlarge_beastcardzoomingratio
                                ? "zoomout_slow" : "zoomout");
                animate(*image, "hide");
            }
        } else if (dynamic_cast<Friend*>(this)) {
            friend_displayed = true;
            self_card->set_pos_noscale(std::nullopt, std::make_tuple(Integer{316}, Integer{142}));
            // Pythonの use_card と同様、Friendを通常の
            // tlayerへ明示的に登録する。 補助処理の既定の対象プレビ
            // ュー層はプレビュー用であり、カード使用時の表示に適用しない。
            ::cw::sprite::card::refresh_card_layer(*self_card, ::cw::layer_val(self_card->m_tlayer));
            animate(self_card, "deal");
            play_card_sound();
            animate(self_card, "zoomin");
            ::cw::g_cwpy->set_inusecardimg(self_card, arg_header, "normal", true, 255, true);
            if (::cw::g_cwpy->m_setting) {
                const auto base = ::cw::g_cwpy->m_setting->get_dealspeed(battle_speed);
                const auto wait = ::cw::g_cwpy->m_setting->m_wait_usecard ? base * 2 + 1 : base + 1;
                ::cw::g_cwpy->wait_frame(wait, ::cw::g_cwpy->m_setting->m_can_skipanimation, std::nullopt, 0);
            }
            if (misfire) {
                ::cw::g_cwpy->clear_inusecardimg(self_card);
                fail_effect(self_card);
                animate(self_card, "hide");
                ::cw::g_cwpy->clear_inusecardimg(std::nullopt);
                animate(self_card, "deal");
                if (::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_zoomout_friend)
                    animate(self_card, "zoomout");
                animate(self_card, "hide");
                self_card->clear_zoomimgs();
                ::cw::sprite::card::remove_from_cardgrp(*self_card);
                friend_displayed = false;
            } else {
                ::cw::g_cwpy->clear_inusecardimg(self_card);
                const bool self_target = std::find(targets.begin(), targets.end(), self_card) != targets.end();
                if (!self_target) {
                    if (::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_zoomout_friend)
                        animate(self_card, "zoomout");
                    animate(self_card, "hide");
                    self_card->clear_zoomimgs();
                    ::cw::sprite::card::remove_from_cardgrp(*self_card);
                    friend_displayed = false;
                }
            }
        } else {
            // Python版と同様、使用中は所有者の通常のカード層を使う。 foreは選
            // 択行動のプレビュー用であり、その後のイベント・メッセージUIには使わない。
            ::cw::g_cwpy->set_inusecardimg(self_card, arg_header, "normal", false, 255, false);
            play_card_sound();
            animate(self_card, "zoomin");
            if (::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_wait_usecard)
                ::cw::g_cwpy->wait_frame(::cw::g_cwpy->m_setting->get_dealspeed(battle_speed),
                                         ::cw::g_cwpy->m_setting->m_can_skipanimation, std::nullopt, 0);
            if (misfire) {
                fail_effect(self_card);
                animate(self_card, "hide");
                ::cw::g_cwpy->clear_inusecardimg(self_card);
                animate(self_card, "deal");
                animate(self_card, "zoomout");
            }
        }
    } else if (!misfire) {
        play_card_sound();
    }

    const auto finish_use = [&] {
        if (!::cw::g_cwpy) return;
        if (friend_displayed && self_card) {
            animate(self_card, "hide");
            self_card->clear_zoomimgs();
            ::cw::sprite::card::remove_from_cardgrp(*self_card);
        }
        ::cw::g_cwpy->m_event->m_in_inusecardevent = false;
    };
    if (misfire) {
        finish_use();
        // カード使用の失敗でも、シナリオの不一致メニューの規則を迂回しない。
        const bool preserve = ::cw::event::is_unmatched_menu_card_use(arg_header, targets);
        if (!preserve)
            arg_header->set_uselimit(-1, true);
        if (::cw::g_cwpy) {
            ::cw::g_cwpy->clear_inusecardimg(std::nullopt);
            ::cw::g_cwpy->clear_specialarea(true, false);
        }
        return !preserve;
    }

    ::cw::lib::Value stored_specialchars{};
    bool stored_specialchars_changed = false;
    bool restore_specialchars = false;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_rsrc) {
        const auto materials = data->find("Property/Materials");
        if (!arg_header->m_scenariocard || (materials && *materials)) {
            stored_specialchars = ::cw::g_cwpy->m_rsrc->m_specialchars;
            stored_specialchars_changed = ::cw::g_cwpy->m_rsrc->m_specialchars_is_changed;
            ::cw::g_cwpy->m_rsrc->m_specialchars = ::cw::g_cwpy->m_rsrc->get_specialchars();
            restore_specialchars = true;
            if (const auto scenario = std::dynamic_pointer_cast<::cw::data::ScenarioData>(current_system_data());
                scenario && ::cw::g_cwpy->is_playingscenario() && materials && *materials && !(*materials)->m_text.empty()) {
                const auto directory = std::filesystem::u8path(::cw::util::join_yadodir((*materials)->m_text));
                std::error_code ec;
                for (std::filesystem::directory_iterator it(directory, ec), end; !ec && it != end; it.increment(ec)) {
                    if (!it->is_regular_file(ec)) continue;
                    scenario->eat_spchar(::cw::lib::encoding::path_to_utf8(it->path().parent_path()),
                                         ::cw::lib::encoding::path_to_utf8(it->path().filename()), data->getbool(".", ::cw::lib::Value("scaledimage"), false));
                }
            }
        }
    }

    std::optional<std::shared_ptr<Element>> event;
    if (const auto found = data->find("Events/Event"); found && *found) event = *found;
    auto cardevent = std::make_shared<::cw::event::CardEvent>();
    cardevent->initialize(event, arg_header,
                          ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(borrowed_character(this))),
                          targets, false);
    try {
        cardevent->start(false);
    } catch (...) {
        if (restore_specialchars && ::cw::g_cwpy && ::cw::g_cwpy->m_rsrc && ::cw::g_cwpy->is_playingscenario()) {
            ::cw::g_cwpy->m_rsrc->m_specialchars = stored_specialchars;
            ::cw::g_cwpy->m_rsrc->m_specialchars_is_changed = stored_specialchars_changed;
        }
        finish_use();
        throw;
    }
    if (restore_specialchars && ::cw::g_cwpy && ::cw::g_cwpy->m_rsrc && ::cw::g_cwpy->is_playingscenario()) {
        ::cw::g_cwpy->m_rsrc->m_specialchars = stored_specialchars;
        ::cw::g_cwpy->m_rsrc->m_specialchars_is_changed = stored_specialchars_changed;
    }
    finish_use();
    if (cardevent->m_no_consume_unmatched_menu_card) return false;
    if (cardevent->::cw::event::Event::m_error && *cardevent->::cw::event::Event::m_error) {
        if (const auto effect_break = std::dynamic_pointer_cast<::cw::event::EffectBreakError>(*cardevent->::cw::event::Event::m_error)) {
            return value_bool(effect_break->m_consumecard);
        }
    }
    return true;
}

void Character::throwaway_card(std::shared_ptr<::cw::header::CardHeader> arg_header, bool arg_from_event, bool arg_update_image)
{
    if (!arg_header) throw std::invalid_argument("Character::throwaway_card requires card header");
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) {
        ::cw::g_cwpy->trade("TRASHBOX", std::nullopt, arg_header, arg_from_event, nullptr, -1, -1,
                            true, true, std::nullopt, false, true, true, arg_update_image, 1);
        return;
    }

    std::vector<std::shared_ptr<::cw::header::CardHeader>>* pocket = nullptr;
    if (arg_header->m_type == "SkillCard") pocket = &std::get<0>(m_cardpocket_typed);
    else if (arg_header->m_type == "ItemCard") pocket = &std::get<1>(m_cardpocket_typed);
    else if (arg_header->m_type == "BeastCard") pocket = &std::get<2>(m_cardpocket_typed);
    else throw std::logic_error("Character::throwaway_card requires a pocket card type");
    const auto found = std::find(pocket->begin(), pocket->end(), arg_header);
    // Pythonの list.remove と同様、一致するヘッダー
    // を一つだけ消し、なければエラーを伝える。 erase/remove
    // で不整合を隠したり、重複する全参照を一度に削除したりしない。
    if (found == pocket->end())
        throw std::logic_error("Character::throwaway_card requires an owned card");
    pocket->erase(found);
    sync_cardpocket_value(*this);
}

void Character::action()
{
    if (!action_is_set(*this)) return;
    const bool is_friend = dynamic_cast<Friend*>(this) != nullptr;
    auto is_hidden = [&] {
        return is_friend ? m__vanished : card_status(*this) == "hidden";
    };
    if (m_reversed || is_hidden()) return;
    const auto beasts = m_action_beasts_typed;
    for (const auto& [targets, header] : beasts) {
        if (!header || !header->is_activewithstatus(borrowed_character(this))) continue;
        bool still_queued = false;
        for (const auto& [unused_targets, queued] : m_action_beasts_typed) {
            (void)unused_targets;
            if (queued == header) {
                still_queued = true;
                break;
            }
        }
        if (!still_queued) continue;
        std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> typed_targets = targets;
        use_card(targets_value(typed_targets), header);
        if (::cw::g_cwpy && ::cw::g_cwpy->is_battlestatus() && ::cw::g_cwpy->m_battle &&
            *::cw::g_cwpy->m_battle && (*::cw::g_cwpy->m_battle)->check_win()) {
            throw ::cw::battle::BattleWinError();
        }
        if (!action_is_set(*this) || is_hidden() || m_reversed || !::cw::g_cwpy || !::cw::g_cwpy->is_battlestatus())
            break;
    }
    if (!is_alive() || is_hidden() || m_reversed || !action_is_set(*this) ||
        !::cw::g_cwpy || !::cw::g_cwpy->is_battlestatus()) return;
    if (!m_action_header_typed || !*m_action_header_typed || !is_active()) return;
    const auto header = *m_action_header_typed;
    if (m_deck) m_deck->set_used(header);
    bool consumecard = true;
    try {
        consumecard = use_card(m_action_target_typed.value_or(::cw::lib::Value{}), header);
    } catch (...) {
        // Pythonのfinallyと同様、効果の後で現在となっているデッキのヘッ
        // ダーを消費する。 画面倍率の変更で、元の複製が置き換わる場合があるため。
        if (m_deck) {
            const auto used = m_deck->get_used();
            if (used && *used) m_deck->use(*used, consumecard);
        }
        throw;
    }
    if (m_deck) {
        const auto used = m_deck->get_used();
        if (used && *used) m_deck->use(*used, consumecard);
    }
}

void Character::set_action(std::optional<::cw::lib::Value> arg_target, std::optional<std::shared_ptr<::cw::header::CardHeader>> arg_header, std::optional<std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>>> arg_beasts, bool arg_py_auto)
{
    const auto beasts = arg_beasts.value_or(std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>>{});
    if (arg_py_auto) {
        clear_action();
        m_action_beasts_typed = beasts;
    } else {
        // Python版と同様、既存の行動タプルがある場合だけ召喚獣を引
        // き継ぎ、最初の手動指定では明示されたものを使う。 ネイティブの
        // タプルは固定長で、clear_action は第三のValue
        // を空にし、 set_action は召喚獣がゼロでも列を保存す
        // る。これで (None,None,[]) の行動も識別する。
        const auto old_beasts = std::get<2>(m_actiondata).is_none() ? beasts : m_action_beasts_typed;
        clear_action();
        m_action_beasts_typed = old_beasts;
    }
    m_action_target_typed = arg_target;
    m_action_header_typed = arg_header;
    m_actionautoselected = arg_py_auto;
    // Python版と同様、対象・ヘッダー・召喚獣を
    // 一つのactiondataとして保つ。 型付き
    // の正のデータと互換表現も同期し、第三のValue
    // が空で自動召喚獣が未指定に見えることを防ぐ。
    auto beast_values = std::make_shared<::cw::data::VariantSequence>();
    for (const auto& [targets, header] : m_action_beasts_typed) {
        auto entry = std::make_shared<::cw::data::VariantSequence>();
        entry->m_values.emplace_back(targets_value(targets));
        entry->m_values.emplace_back(header
            ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(header))
            : ::cw::lib::Value{});
        beast_values->m_values.emplace_back(
            ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(entry)));
    }
    m_actiondata = {arg_target.value_or(::cw::lib::Value{}),
                    arg_header && *arg_header ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*arg_header)) : ::cw::lib::Value{},
                    ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(beast_values))};
    m_actionend = false;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_battle && *::cw::g_cwpy->m_battle && arg_target && arg_header && *arg_header) {
        _add_priorityacts(*arg_target, *arg_header);
    }
    if (!arg_py_auto) {
        if (::cw::g_cwpy) {
            ::cw::g_cwpy->play_sound("page", false, 100, 1, 0, 0, false);
            // UI履歴の項目がなくても、エンジンを終了させない。 履
            // 歴は対象選択をキャンセルするときにCardControl
            // を開き直すためだけに使い、選択した行動自体は有効。
            if (!::cw::g_cwpy->m_pre_dialogs.empty())
                ::cw::g_cwpy->m_pre_dialogs.pop_back();
        }
    }
}

void Character::replace_action_header(
    const std::shared_ptr<::cw::header::CardHeader>& arg_old,
    const std::shared_ptr<::cw::header::CardHeader>& arg_replacement)
{
    if (!arg_old || !arg_replacement) return;
    if (m_action_header_typed && *m_action_header_typed == arg_old)
        m_action_header_typed = arg_replacement;
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&std::get<1>(m_actiondata).storage());
    if (object && *object && std::dynamic_pointer_cast<::cw::header::CardHeader>(*object) == arg_old)
        std::get<1>(m_actiondata) = ::cw::lib::Value(
            std::static_pointer_cast<::cw::lib::Object>(arg_replacement));
}

void Character::_add_priorityacts(::cw::lib::Value arg_target, std::shared_ptr<::cw::header::CardHeader> arg_h)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_battle || !*::cw::g_cwpy->m_battle || !arg_h || !has_target_value(arg_target)) return;
    const auto motions = _get_motions(arg_h);
    if (!motions) return;
    for (const auto& motion : motions->m_children) {
        if (!motion) continue;
        const auto type = motion->get("type", "");
        if (!_is_bonusedmtype(type)) continue;
        auto& priorityacts = arg_h->m_type == "BeastCard"
            ? (*::cw::g_cwpy->m_battle)->m_priorityacts_beast
            : (*::cw::g_cwpy->m_battle)->m_priorityacts;
        priorityacts.emplace_back(type, arg_target, borrowed_character(this));
    }
}

void Character::adjust_action()
{
    if (action_is_set(*this) && is_inactive(false)) {
        set_action(std::nullopt, std::nullopt, m_action_beasts_typed, true);
    }
    if (is_inactive(false) && m_deck) m_deck->throwaway();
    if ((is_unconscious() || is_paralyze() || is_sleep()) && m_deck) m_deck->clear_nextcards();
}

void Character::clear_action()
{
    m_actiondata = {};
    m_action_target_typed.reset();
    m_action_header_typed.reset();
    m_action_beasts_typed.clear();
    m_actionautoselected = false;
    m_actionend = true;
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_battle || !*::cw::g_cwpy->m_battle) return;
    auto& battle = **::cw::g_cwpy->m_battle;
    const auto user = borrowed_character(this);
    std::erase_if(battle.m_priorityacts, [&user](const auto& item) { return std::get<2>(item) == user; });
    // Python版と同様、ここでは priorityacts_beast を意図的
    // に残す。 優先順位は set_action(auto=True) より先に集め
    // るため、 その最初の clear_action() で直前の選択を消さない。
}

bool Character::is_autoselectedpenalty(std::optional<std::shared_ptr<::cw::header::CardHeader>> arg_header)
{
    // 選択行動にヘッダーがなければ、型付きのbool条件はfalseにする。 Python
    // 版は同じ分岐でheaderpの短絡評価によりNoneを返す場合がある。
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_battle || !*::cw::g_cwpy->m_battle || !m_actionautoselected || !m_action_header_typed) return false;
    const auto header = *m_action_header_typed;
    return header && header->m_penalty && (!arg_header || *arg_header == header);
}

bool Character::decide_outcome(::cw::lib::Integer arg_level, std::tuple<::cw::lib::String, ::cw::lib::String> arg_vocation, ::cw::lib::Integer arg_thresholdbonus, ::cw::lib::Integer arg_enhance, ::cw::lib::Integer arg_subbonus)
{
    const auto dice = roll_dice(2);
    if (dice == 12) return true;
    if (dice == 2) return false;
    const auto udice = roll_dice(2);
    const auto voc = get_vocation_val(std::move(arg_vocation));
    const auto uvalue = ::cw::util::div_vocation(static_cast<Integer>(arg_thresholdbonus)) + arg_level + arg_subbonus + udice;
    const auto tvalue = ::cw::util::div_vocation(voc + arg_enhance) + m_level + dice;
    return uvalue <= tvalue;
}

bool Character::decide_misfire(::cw::lib::Integer arg_level)
{
    const auto dice = roll_dice(2);
    return dice == 12 || dice >= arg_level - m_level - 1;
}

::cw::lib::Integer Character::decide_actionorder()
{
    const auto vocation_val = get_vocation_val({"agl", "uncautious"});
    // Pythonのint(float)境界。有限性とInteger範囲を確認してから丸める。
    const auto base = real_to_integer((vocation_val + 1) * 1.4).value_or(0);
    m_actionorder = base + roll_dice(2, 6);
    return m_actionorder;
}

void Character::decide_action()
{
    clear_action();
    if (!::cw::g_cwpy || ::cw::g_cwpy->m_status != "ScenarioBattle") return;

    std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>> beasts;
    for (const auto& header : get_pocketcards(::cw::g_POCKET_BEAST)) {
        if (!header || !header->is_autoselectable() || !header->is_activewithstatus(borrowed_character(this))) continue;
        const auto [targets, effective] = header->get_targets();
        if (effective.empty()) continue;
        const auto [bonus, preferred] = _get_targetingbonus_and_targets(header, effective, true);
        (void)bonus;
        auto selected_targets = targets;
        if (!header->m_allrange && selected_targets.size() > 1) {
            const auto selected = choose_card(preferred);
            selected_targets = selected ? std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>{selected} : std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>{};
        }
        beasts.emplace_back(selected_targets, header);
        _add_priorityacts(targets_value(selected_targets), header);
    }
    if (is_inactive()) {
        set_action(std::nullopt, std::nullopt, beasts, true);
        return;
    }

    std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>> headers;
    // Python版と同様、選択は deck.hand から行う。 使用済み
    // カードも含む、表示・検索用の get_hand() の一覧は使わない。
    const auto hand = m_deck ? m_deck->m_hand : std::vector<std::shared_ptr<::cw::header::CardHeader>>{};
    for (const auto& header : hand) {
        if (!header || !header->is_autoselectable()) continue;
        const auto [targets, effective] = header->get_targets();
        if (effective.empty() && header->m_target != "None") continue;
        headers.emplace_back(header->m_allrange ? targets : effective, header);
    }
    auto [targets, header] = decide_usecard(std::move(headers));
    if (header && !(*header)->m_allrange && targets.size() > 1) {
        if (const auto selected = choose_card(targets)) targets = {selected};
    }
    set_action(targets_value(targets), header, beasts, true);
}

std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::optional<std::shared_ptr<::cw::header::CardHeader>>> Character::decide_usecard(std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>> arg_headers)
{
    std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>> seq;
    std::vector<std::tuple<std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>, std::shared_ptr<::cw::header::CardHeader>>> exchange;
    for (const auto& item : arg_headers) {
        const auto& header = std::get<1>(item);
        if (header && header->m_type == "ActionCard" && header->m_id == 0) exchange.push_back(item);
        else seq.push_back(item);
    }
    seq.insert(seq.end(), exchange.begin(), exchange.end());
    Integer maxd = std::numeric_limits<Integer>::min();
    std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> selected_targets;
    std::shared_ptr<::cw::header::CardHeader> selected_header;
    for (std::size_t i = 0; i < seq.size(); ++i) {
        const auto& targets = std::get<0>(seq[i]);
        const auto& header = std::get<1>(seq[i]);
        if (!header) continue;
        auto vocation = header->get_vocation_val(borrowed_character(this), false);
        if (i >= seq.size() - exchange.size()) vocation -= 6;
        else vocation = std::max<Integer>(0, vocation);
        const auto [bonus, targeting] = _get_targetingbonus_and_targets(header, targets, false);
        const auto numerator = 1 + vocation;
        const auto value = numerator / 2 - (numerator % 2 < 0 ? 1 : 0) + roll_dice() + bonus;
        if (maxd < value) {
            maxd = value;
            selected_targets = targeting;
            selected_header = header;
        }
    }
    // Python版と同様、カード未選択なら ([], None) を返す。 nullの shared_ptr
    // を格納した有効なoptionalはNoneではなく、呼び出し元が参照してしまうため使わない。
    return {selected_targets, selected_header
        ? std::optional<std::shared_ptr<::cw::header::CardHeader>>(selected_header)
        : std::nullopt};
}

std::shared_ptr<::cw::data::CWPyElement> Character::_get_motions(std::shared_ptr<::cw::header::CardHeader> arg_header)
{
    if (!arg_header) throw std::invalid_argument("_get_motions requires card header");
    if (arg_header->m_type == "ActionCard" && arg_header->m_id == 7) {
        return ::cw::data::make_element("Motion", "", std::map<String, String>{{"type", "Runaway"}});
    }
    const auto data = value_element(arg_header->m_carddata);
    if (!data) throw std::logic_error("_get_motions requires card XML");
    return data->find_exists("Motions");
}

bool Character::_is_bonusedmtype(::cw::lib::String arg_mtype)
{
    return arg_mtype == "Runaway" || arg_mtype == "Heal";
}

std::tuple<::cw::lib::Integer, std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>>> Character::_get_targetingbonus_and_targets(std::shared_ptr<::cw::header::CardHeader> arg_header, std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> arg_targets, bool arg_beast)
{
    const auto original_targets = arg_targets;
    Integer bonus = std::numeric_limits<Integer>::min();
    std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> max_targets;
    const auto motions_root = _get_motions(arg_header);
    std::vector<std::shared_ptr<Element>> selected_motions;
    if (motions_root) {
        for (const auto& motion : motions_root->m_children) {
            if (!motion) continue;
            const auto type = motion->get("type", "");
            bool updated = false;
            bool some = false;
            for (const auto& target : arg_targets) {
                const auto character = target ? std::dynamic_pointer_cast<Character>(target) : nullptr;
                if (!character || !character->is_effective(arg_header, motion)) continue;
                const auto value = _is_bonusedmtype(type) ? character->get_targetingbonus(type, arg_beast) : 0;
                if (bonus == value) {
                    if (std::find(max_targets.begin(), max_targets.end(), target) == max_targets.end()) max_targets.push_back(target);
                    some = true;
                } else if (bonus < value) {
                    max_targets = {target};
                    bonus = value;
                    updated = true;
                }
            }
            if (updated) selected_motions = {motion};
            else if (some) selected_motions.push_back(motion);
        }
    }
    if (bonus == std::numeric_limits<Integer>::min()) {
        bonus = 0;
    } else {
        arg_targets = max_targets;
    }
    if (!arg_header || arg_header->m_allrange) return {bonus, original_targets};
    for (const auto& motion : selected_motions) {
        std::vector<std::shared_ptr<::cw::sprite::card::CWPyCard>> filtered;
        for (const auto& target : arg_targets) {
            const auto character = target ? std::dynamic_pointer_cast<Character>(target) : nullptr;
            if (character && character->is_effective(arg_header, motion)) filtered.push_back(target);
        }
        if (!filtered.empty()) return {bonus, filtered};
    }
    return {bonus, arg_targets};
}

::cw::lib::Integer Character::get_targetingbonus(::cw::lib::String arg_mtype, bool arg_beast)
{
    Integer bonus = 0;
    const auto per = get_lifeper();
    if (arg_mtype == "Heal") {
        if (per >= 50) bonus = -1;
        else if (per >= 33) bonus = 0;
        else if (per >= 25) bonus = 1;
        else if (per >= 20) bonus = 2;
        else if (per >= 16) bonus = 3;
        else if (per >= 14) bonus = 4;
        else if (per >= 12) bonus = 5;
        else if (per >= 1) bonus = 6 + (11 - per);
        else bonus = std::max<Integer>(17, m_maxlife);
    } else if (arg_mtype == "Runaway") {
        if (per >= 50) bonus = 3;
        else if (per >= 33) bonus = 4;
        else if (per >= 25) bonus = 5;
        else if (per >= 20) bonus = 6;
        else if (per >= 16) bonus = 7;
        else if (per >= 14) bonus = 8;
        else if (per >= 12) bonus = 9;
        else bonus = 10 + (11 - per);
    }

    if (::cw::g_cwpy && ::cw::g_cwpy->m_battle && *::cw::g_cwpy->m_battle) {
        const auto& priorityacts = arg_beast ? (*::cw::g_cwpy->m_battle)->m_priorityacts_beast : (*::cw::g_cwpy->m_battle)->m_priorityacts;
        const auto self = borrowed_character(this);
        const auto self_card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(self);
        Integer targeting = 0;
        for (const auto& [type, target, unused] : priorityacts) {
            (void)unused;
            if (type != arg_mtype) continue;
            const auto* object = std::get_if<::cw::lib::ObjectPtr>(&target.storage());
            if (!object || !*object) continue;
            if (const auto character = std::dynamic_pointer_cast<Character>(*object)) {
                if (character == self) ++targeting;
            } else if (self_card) {
                for (const auto& card : value_targets(target)) {
                    if (card == self_card) {
                        ++targeting;
                        break;
                    }
                }
            }
        }
        if (targeting > 0) {
            bonus = std::min<Integer>(0, bonus);
            if (arg_mtype == "Heal") bonus -= targeting;
        }
    }
    return bonus;
}

std::vector<std::shared_ptr<::cw::header::CardHeader>> Character::get_pocketcards(::cw::lib::Integer arg_index)
{
    arg_index = three_item_index(arg_index);
    if (arg_index == 0) return std::get<0>(m_cardpocket_typed);
    if (arg_index == 1) return std::get<1>(m_cardpocket_typed);
    if (arg_index == 2) return std::get<2>(m_cardpocket_typed);
    throw std::out_of_range("card pocket index");
}

std::tuple<::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer> Character::get_cardpocketspace()
{
    const auto clamp_capacity = [](::cw::lib::Integer value) {
        return std::clamp<::cw::lib::Integer>(value, 1, 10);
    };
    const auto level_skill = clamp_capacity(m_level / 2 + m_level % 2 + 2);
    const auto skill = has_expanded_pc_card_limits()
        ? configured_pc_capacity("pcSkillLimit", level_skill) : level_skill;
    auto beast = (m_level + 2) / 4;
    if ((m_level + 2) % 4 != 0) {
        ++beast;
    }
    beast = clamp_capacity(beast);
    // 宿のPCカード上限は、召喚獣カードの容量も増やす。
    if (has_expanded_pc_card_limits()) beast = configured_pc_capacity("pcBeastLimit", beast);
    return {skill, level_skill, beast};
}

bool Character::has_expanded_pc_card_limits() const
{
    if (!dynamic_cast<const Player*>(this)) return false;
    const auto inn = ::cw::g_cwpy && ::cw::g_cwpy->m_ydata ? *::cw::g_cwpy->m_ydata : nullptr;
    return ::cw::pc_card_limits::read(inn).enabled;
}

::cw::lib::Real Character::skill_distribution_rate()
{
    if (!has_expanded_pc_card_limits()) return 1.0;
    const auto baseline = std::clamp<Integer>(m_level / 2 + m_level % 2 + 2, 1, 10);
    const auto count = static_cast<Integer>(get_pocketcards(::cw::g_POCKET_SKILL).size());
    return ::cw::skill_distribution::rate(baseline, count);
}

::cw::lib::Integer Character::calc_lifeper(::cw::lib::Integer arg_life, ::cw::lib::Integer arg_maxlife)
{
    if (arg_maxlife == 0) throw std::invalid_argument("calc_lifeper requires a non-zero maxlife");
    // Pythonの int(100.0 * life // maxlife + 0.5)
    // に合わせる。 特に最後のintは、0.5を加えた後の負値をゼロ方向へ切り捨てる。
    const Real rounded = ::cw::lib::python_float_floor_divide(
        100.0 * static_cast<Real>(arg_life), static_cast<Real>(arg_maxlife)) + 0.5;
    if (const auto result = real_to_integer(rounded)) return *result;
    // ネイティブの公開戻り型は、Pythonのintと異なり符号付き
    // 64ビット。 表せない結果を黙ってゼロにせず、失敗を報告する。
    throw std::overflow_error("calc_lifeper result exceeds native Integer");
}

::cw::lib::Integer Character::get_lifeper()
{
    return calc_lifeper(m_life, m_maxlife);
}

::cw::lib::Integer Character::get_bonus(std::tuple<::cw::lib::String, ::cw::lib::String> arg_vocation, bool arg_enhance_act)
{
    auto value = get_vocation_val(std::move(arg_vocation));
    if (arg_enhance_act) {
        value += get_enhance_act();
    }
    return value;
}

::cw::lib::Integer Character::get_vocation_val(std::tuple<::cw::lib::String, ::cw::lib::String> arg_vocation)
{
    if (const auto found = m__voc_tbl.find(arg_vocation);
        found != m__voc_tbl.end() && found->second.has_value()) {
        return *found->second;
    }

    auto physical_name = std::get<0>(arg_vocation);
    auto mental_name = std::get<1>(arg_vocation);
    const auto lower_ascii = [](::cw::lib::String& text) {
        std::transform(text.begin(), text.end(), text.begin(), [](unsigned char ch) {
            return static_cast<char>(std::tolower(ch));
        });
    };
    lower_ascii(physical_name);
    lower_ascii(mental_name);

    const bool invert_mental = mental_name.find("un") != ::cw::lib::String::npos;
    if (const auto pos = mental_name.find("un"); pos != ::cw::lib::String::npos) {
        mental_name.erase(pos, 2);
    }

    const auto physical = m_physical.at(physical_name);
    auto mental = m_mental.at(mental_name);
    if (invert_mental) {
        mental = -mental;
    }
    // Pythonのint()と同じく0方向へ丸める。
    const auto mental_integer = real_to_integer(mental);
    if (!mental_integer) {
        mental = 0.0;
    } else if (static_cast<Real>(*mental_integer) != mental) {
        mental += mental < 0 ? 0.5 : -0.5;
        mental = static_cast<Real>(real_to_integer(mental).value_or(0));
    }
    auto vocation = real_to_integer(physical + mental).value_or(0);
    vocation = std::clamp<::cw::lib::Integer>(vocation, -65536, 65536);
    m__voc_tbl[arg_vocation] = vocation;
    return vocation;
}

void Character::_clear_vocationcache()
{
    m__voc_tbl.clear();
}

::cw::lib::Integer Character::get_enhance_act()
{
    return std::clamp<::cw::lib::Integer>(m_enhance_act, -10, 10);
}

::cw::lib::Real Character::get_enhance_def()
{
    std::vector<Real> bonus_values;
    std::vector<Real> penalty_values;
    const auto [ivalue, max10] = _get_enhance_impl_i("defense", m_enhance_def, 2, std::nullopt);
    if (max10 > 0 || ivalue >= 10 || ivalue <= -10) return static_cast<Real>(ivalue);
    for (const auto btype : {s__BTYPE_SKILL, s__BTYPE_ITEM_USE, s__BTYPE_ITEM, s__BTYPE_BEAST,
                             s__BTYPE_ACTION, s__BTYPE_CAST, s__BTYPE_STATUS}) {
        const auto value = _get_enhance_impl_f("defense", m_enhance_def, 2, btype);
        if (value > 0) bonus_values.push_back(10.0 - static_cast<Real>(value));
        else if (value < 0) penalty_values.push_back(10.0 - static_cast<Real>(value));
    }
    const auto aggregate = [](const std::vector<Real>& values) {
        if (values.empty()) return 0.0;
        Real product = 1.0;
        for (const auto value : values) product *= value;
        return (std::pow(10.0, static_cast<Real>(values.size())) - product) /
               std::pow(10.0, static_cast<Real>(values.size() - 1));
    };
    return aggregate(bonus_values) + aggregate(penalty_values);
}

::cw::lib::Integer Character::get_enhance_res()
{
    return std::get<0>(_get_enhance_impl_i("resist", m_enhance_res, 1, std::nullopt));
}

::cw::lib::Integer Character::get_enhance_avo()
{
    return std::get<0>(_get_enhance_impl_i("avoid", m_enhance_avo, 0, std::nullopt));
}

::cw::lib::Real Character::_get_enhance_impl_f(::cw::lib::String arg_name, ::cw::lib::Integer arg_initvalue, ::cw::lib::Integer arg_enhindex, std::optional<::cw::lib::Integer> arg_btype)
{
    const auto [a, b, max10] = _get_enhance_impl(std::move(arg_name), arg_initvalue, arg_enhindex, arg_btype);
    const auto value = b - a;
    if (max10 > 0) return 10.0;
    return std::clamp<Real>(value, -10.0, 9.9);
}

std::tuple<::cw::lib::Integer, ::cw::lib::Integer> Character::_get_enhance_impl_i(::cw::lib::String arg_name, ::cw::lib::Integer arg_initvalue, ::cw::lib::Integer arg_enhindex, std::optional<::cw::lib::Integer> arg_btype)
{
    const auto [a, b, max10] = _get_enhance_impl(std::move(arg_name), arg_initvalue, arg_enhindex, arg_btype);
    const auto converted = real_to_integer(b - a);
    auto value = converted.value_or(0);
    if (max10 > 0) value += (max10 - 1) * 5;
    return {value, max10};
}

std::tuple<::cw::lib::Real, ::cw::lib::Real, ::cw::lib::Integer> Character::_get_enhance_impl(::cw::lib::String arg_name, ::cw::lib::Integer arg_initvalue, ::cw::lib::Integer arg_enhindex, std::optional<::cw::lib::Integer> arg_btype)
{
    const auto find_base = m_enhance_typed.find(arg_name);
    const Real raw_val1 = find_base != m_enhance_typed.end()
                              ? find_base->second
                              : static_cast<Real>(m_enhance.at(arg_name));
    const Integer val1 = std::clamp<Integer>(real_to_integer(raw_val1).value_or(0), -10, 10);
    const Integer val2 = std::clamp<Integer>(arg_initvalue, -10, 10);
    std::vector<Integer> values;
    if (!arg_btype || *arg_btype == s__BTYPE_CAST) values.push_back(val1);
    if (!arg_btype || *arg_btype == s__BTYPE_STATUS) values.push_back(val2);
    std::vector<Integer> pvals;
    const auto add_pval = [&pvals](Real value) {
        if (0 < value && value < 10) {
            if (const auto integer = real_to_integer(value)) pvals.push_back(*integer);
        }
        else if (value == 10) pvals.clear();
    };
    const auto wrap_enhval = [](Integer value, Integer original) {
        if (original < 0) return std::clamp<Integer>(value, -10, -1);
        if (original > 0) return std::clamp<Integer>(value, 1, 10);
        return Integer{0};
    };
    const auto addval = [&](const std::shared_ptr<::cw::header::CardHeader>& header, Integer input, bool using_card) {
        if (!header) return;
        Real value = static_cast<Real>(input);
        const Integer original = input;
        if (header->m_type == "SkillCard") {
            if (arg_btype && *arg_btype != s__BTYPE_SKILL) return;
            if (!using_card) throw std::logic_error("SkillCard enhancement must be from active card");
            if (-10 < value && value < 10 && header->get_vocation_level(borrowed_character(this), false) >= 2) value *= 1.2;
            add_pval(value);
            value = static_cast<Real>(original);
        } else if (header->m_type == "ItemCard" && using_card) {
            if (arg_btype && *arg_btype != s__BTYPE_ITEM_USE) return;
            add_pval(value);
        } else if (header->m_type == "ItemCard") {
            if (arg_btype && *arg_btype != s__BTYPE_ITEM) return;
            if (-10 < value && value < 0) {
                const auto level = header->get_vocation_level(borrowed_character(this), false);
                if (level >= 3) value *= 0.8;
                else if (level <= 0) value *= 1.2;
                value = std::clamp<Real>(value, -9.0, -1.0);
            } else if (0 < value && value < 10) {
                const auto level = header->get_vocation_level(borrowed_character(this), false);
                if (level <= 0) value *= 0.5;
                else if (level <= 1) value *= 0.8;
                value = std::clamp<Real>(value, 1.0, 9.0);
            }
            add_pval(value);
        } else if (header->m_type == "BeastCard") {
            if (arg_btype && *arg_btype != s__BTYPE_BEAST) return;
            add_pval(value);
        } else {
            if (header->m_type != "ActionCard") throw std::logic_error("unknown card type in enhancement");
            if (arg_btype && *arg_btype != s__BTYPE_ACTION) return;
            add_pval(value);
        }
        values.push_back(wrap_enhval(real_to_integer(value).value_or(0), original));
    };

    const auto tuple_value = [arg_enhindex](const std::tuple<Integer, Integer, Integer>& values) {
        const auto index = three_item_index(arg_enhindex);
        if (index == 0) return std::get<0>(values);
        if (index == 1) return std::get<1>(values);
        return std::get<2>(values);
    };
    std::shared_ptr<::cw::header::CardHeader> active_header;
    if (m_action_header_typed && *m_action_header_typed) active_header = *m_action_header_typed;
    else if (m_deck) {
        const auto used = m_deck->get_used();
        if (used && *used) active_header = *used;
    }
    if (active_header) {
        const auto used_values = active_header->get_enhance_val_used();
        addval(active_header, tuple_value(used_values), true);
    }
    for (const auto& header : get_pocketcards(::cw::g_POCKET_BEAST)) {
        if (!header) continue;
        const auto values_card = header->get_enhance_val();
        addval(header, tuple_value(values_card), false);
    }
    for (const auto& header : get_pocketcards(::cw::g_POCKET_ITEM)) {
        if (!header) continue;
        const auto values_card = header->get_enhance_val();
        addval(header, tuple_value(values_card), false);
    }
    if (!arg_btype || *arg_btype == s__BTYPE_CAST) add_pval(static_cast<Real>(val1));
    if (!arg_btype || *arg_btype == s__BTYPE_STATUS) add_pval(static_cast<Real>(val2));

    Real a = 0.0;
    Real b = 0.0;
    Integer ac = 0;
    Integer bc = 0;
    Integer minval = 0;
    Integer maxval = 0;
    Integer max10 = 0;
    for (const auto value : values) {
        if (value < 0) {
            a = a == 0.0 ? 10.0 + value : a * (10.0 + value);
            ++ac;
            minval = std::min<Integer>(minval, value);
        } else if (value > 0) {
            b = b == 0.0 ? 10.0 - value : b * (10.0 - value);
            ++bc;
            maxval = std::max<Integer>(maxval, value);
            max10 += value / 10;
        }
    }
    if (ac > 0) {
        a /= std::pow(10.0, static_cast<Real>(ac - 1));
        a = std::max<Real>(static_cast<Real>(-minval), 10.0 - a);
    }
    if (bc > 0) {
        b /= std::pow(10.0, static_cast<Real>(bc - 1));
        b = std::max<Real>(static_cast<Real>(maxval), 10.0 - b);
    }
    long long pvalr = 100;
    for (auto it = pvals.rbegin(); it != pvals.rend(); ++it) {
        pvalr *= 10;
        pvalr *= 10 - *it;
        pvalr /= 100;
    }
    if (pvalr < 1) ++max10;
    if (max10 > 0 && b < 10.0) b = 10.0;
    return {a, b, max10};
}

std::set<::cw::lib::String> Character::get_coupons()
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _get_coupons();
}

// 称号APIは、旧Valueマップと型付きの値・XMLマップを同期する。
// 旧マップの直接編集はここでのキー列挙に影響するが、型付きの値、特殊称
// 号の読み取り、 取得済みの時間制限付き称号集合は更新しない。 一つの
// 辞書を正とするPython版とは異なるため、変更は公開APIを使う。
std::set<::cw::lib::String> Character::_get_coupons()
{
    std::set<String> result;
    for (const auto& [name, unused] : m_coupons) {
        (void)unused;
        result.insert(name);
    }
    return result;
}

std::optional<::cw::lib::Integer> Character::get_couponvalue(::cw::lib::String arg_name, bool arg_raiseerror)
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _get_couponvalue(std::move(arg_name), arg_raiseerror);
}

// 値は直接編集された旧Value項目ではなく、型付きの称号・XML
// 表から読む。 公開の称号書き込み処理は、両方の表現を更新する。
std::optional<::cw::lib::Integer> Character::_get_couponvalue(::cw::lib::String arg_name, bool arg_raiseerror)
{
    const auto found = m_coupons_typed.find(arg_name);
    if (found != m_coupons_typed.end()) return std::get<0>(found->second);
    if (arg_raiseerror) throw std::out_of_range("coupon not found: " + arg_name);
    return std::nullopt;
}

bool Character::has_coupon(::cw::lib::String arg_coupon)
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _has_coupon(std::move(arg_coupon));
}

bool Character::_has_coupon(::cw::lib::String arg_coupon)
{
    return m_coupons.find(arg_coupon) != m_coupons.end();
}

bool Character::has_coupon_nolock(::cw::lib::String arg_coupon)
{
    return _has_coupon(std::move(arg_coupon));
}

::cw::lib::Integer Character::get_couponsvalue()
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _get_couponsvalue();
}

::cw::lib::Integer Character::_get_couponsvalue()
{
    Integer result = 0;
    for (const auto& [name, typed] : m_coupons_typed) {
        if (!name.empty() && name.rfind("＠", 0) != 0 && name.rfind("：", 0) != 0 && name.rfind("；", 0) != 0) {
            result += std::get<0>(typed);
        }
    }
    return result;
}

std::map<::cw::lib::String, ::cw::lib::Integer> Character::get_specialcoupons()
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _get_specialcoupons();
}

// 特殊称号も get_couponvalue と同じ型付き表を使う。 Python
// 版は一つの辞書を絞り込むが、ネイティブの旧表の直接編集は別に扱う。
std::map<::cw::lib::String, ::cw::lib::Integer> Character::_get_specialcoupons()
{
    std::map<String, Integer> result;
    for (const auto& [name, typed] : m_coupons_typed) if (name.rfind("＠", 0) == 0) result[name] = std::get<0>(typed);
    return result;
}

// 型付きの値・XML表を基準に比較・再構築する。 旧表の直接編集は、Python
// のcoupons辞書の編集と異なり、その基準値を置き換えない。
bool Character::replace_allcoupons(std::vector<std::tuple<::cw::lib::String, ::cw::lib::Integer>> arg_seq, std::optional<::cw::lib::Value> arg_syscoupons)
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    if (!is_card_character(*this)) throw std::logic_error("replace_allcoupons requires card character");
    std::set<String> system_coupons;
    if (arg_syscoupons) for (const auto& name : value_strings(*arg_syscoupons)) system_coupons.insert(name);
    std::map<String, Integer> old;
    for (const auto& [name, typed] : m_coupons_typed) old[name] = std::get<0>(typed);
    bool old_reversed = false;
    bool new_reversed = false;
    for (const auto& name : _get_coupons()) {
        old_reversed = old_reversed || name == "：Ｒ";
        if (name.empty() || (name.rfind("＠", 0) != 0 && system_coupons.find(name) == system_coupons.end())) _remove_coupon(name, false);
    }
    // init_skin は旧Value表ではなく、共通の型付き称号一覧を設定する。
    const auto sex = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::setting::Setting::s_sexcoupons : std::vector<String>{};
    const auto periods = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::setting::Setting::s_periodcoupons : std::vector<String>{};
    const auto natures = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::setting::Setting::s_naturecoupons : std::vector<String>{};
    for (const auto& [name, value] : arg_seq) {
        if (std::find(sex.begin(), sex.end(), name) != sex.end()) {
            const auto old_name = _get_sex();
            if (!old_name.empty()) _remove_coupon(old_name, true);
        }
        if (std::find(periods.begin(), periods.end(), name) != periods.end()) {
            const auto old_name = _get_age();
            if (!old_name.empty()) _remove_coupon(old_name, true);
        }
        if (std::find(natures.begin(), natures.end(), name) != natures.end()) {
            const auto old_name = _get_talent();
            if (!old_name.empty()) _remove_coupon(old_name, true);
        }
        _set_coupon(name, value, false);
        new_reversed = new_reversed || name == "：Ｒ";
    }
    if (old_reversed != new_reversed) {
        m_reversed = old_reversed;
        set_coupon_reverse_state(*this, new_reversed, true, false);
    }
    std::map<String, Integer> current;
    for (const auto& [name, typed] : m_coupons_typed) current[name] = std::get<0>(typed);
    return old != current;
}

