void Character::_set_coupon(::cw::lib::String arg_name, ::cw::lib::Integer arg_value, bool arg_update)
{
    if (!is_card_character(*this)) throw std::logic_error("set_coupon requires card character");
    mark_yado_changed();
    arg_value = std::clamp<Integer>(arg_value, -9999, 9999);
    const bool removed = _remove_coupon(arg_name, false);
    auto coupon = ::cw::data::make_element("Coupon", arg_name, std::map<String, String>{{"value", std::to_string(arg_value)}});
    if (const auto coupons = ensure_coupons_element(*this)) coupons->append(coupon);
    m_coupons[arg_name] = arg_value;
    m_coupons_typed[arg_name] = {arg_value, coupon};
    if (is_timed_coupon(arg_name)) m_timedcoupons_typed.insert(arg_name);
    if (arg_name == "：Ｒ" && !m_reversed)
        set_coupon_reverse_state(*this, true, arg_update && !removed);
    if (!removed && arg_name == "＠効果対象" && ::cw::g_cwpy && ::cw::g_cwpy->m_event) {
        if (const auto effect = ::cw::g_cwpy->m_event->get_effectevent(); effect && *effect) (*effect)->add_target(borrowed_character(this));
    }
    mark_edited(*this);
    adjust_action();
}

// 型付きの所属キャッシュを優先し、空の場合だけ旧マップから名前を求める
// 。 直接編集は取得済みキャッシュを無効にしない。 Python版のtimedcoupons
// も、公開の変更処理の寿命管理を通じて取得する。
std::set<::cw::lib::String> Character::get_timedcoupons()
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    if (!m_timedcoupons_typed.empty()) return m_timedcoupons_typed;
    std::set<String> result;
    for (const auto& [name, unused] : m_coupons) {
        (void)unused;
        if (is_timed_coupon(name)) result.insert(name);
    }
    return result;
}

bool Character::remove_coupon(::cw::lib::String arg_name)
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _remove_coupon(std::move(arg_name), true);
}

bool Character::_remove_coupon(::cw::lib::String arg_name, bool arg_update)
{
    const auto found = m_coupons.find(arg_name);
    if (found == m_coupons.end()) return false;
    mark_yado_changed();
    const auto typed = m_coupons_typed.find(arg_name);
    if (m_data_typed) {
        if (const auto coupons = m_data_typed->find("Property/Coupons"); coupons && *coupons) {
            if (typed != m_coupons_typed.end() && std::get<1>(typed->second)) (*coupons)->remove(std::get<1>(typed->second));
            else {
                for (const auto& child : (*coupons)->m_children) if (child && child->m_text == arg_name) { (*coupons)->remove(child); break; }
            }
        }
    }
    m_coupons.erase(found);
    m_coupons_typed.erase(arg_name);
    m_timedcoupons_typed.erase(arg_name);
    if (arg_name == "：Ｒ" && m_reversed)
        set_coupon_reverse_state(*this, false, arg_update);
    if (arg_name == "＠効果対象" && ::cw::g_cwpy && ::cw::g_cwpy->m_event) {
        if (const auto effect = ::cw::g_cwpy->m_event->get_effectevent(); effect && *effect) (*effect)->remove_target(borrowed_character(this));
    }
    mark_edited(*this);
    return true;
}

void Character::reverse()
{
    const bool old_reversed = m_reversed;
    m_reversed = !old_reversed;
    if (const auto card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(borrowed_character(this))) {
        // Pythonの単一属性とは異なり、ネイティブの二つの基底が別々に設定されてい
        // る場合がある。 Characterの元の状態を基準に、切り替えと描画を行う。
        card->m_reversed = old_reversed;
        card->reverse();
        card->m_reversed = m_reversed;
    }
}

