    mark_yado_changed();
    if (is_unconscious()) arg_value = 0;
    m_bind = std::clamp<::cw::lib::Integer>(arg_overwrite ? arg_value : std::max(m_bind, arg_value), 0, 999);
    edit_character_xml(*this, "Property/Status/Bind", std::to_string(m_bind), std::optional<String>("duration"));
