void Character::set_vanish(bool arg_battlespeed)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("set_vanish requires yado party");
    const auto yado = *::cw::g_cwpy->m_ydata;
    const auto party = *yado->m_party;
    const auto scenario = current_system_data() ? std::dynamic_pointer_cast<::cw::data::ScenarioData>(current_system_data()) : nullptr;
    const auto scenario_hint = scenario ? scenario->get_versionhint(::cw::g_HINT_SCENARIO) : std::nullopt;
    if (dynamic_cast<Friend*>(this) && ::cw::g_cwpy->m_sct &&
        ::cw::g_cwpy->m_sct->lessthan("1.50", scenario_hint)) {
        yado->changed();
        if (::cw::g_cwpy->is_battlestatus() && ::cw::g_cwpy->m_battle && *::cw::g_cwpy->m_battle) {
            auto& members = (*::cw::g_cwpy->m_battle)->m_members;
            const auto self = borrowed_character(this);
            if (const auto found = std::find(members.begin(), members.end(), self); found != members.end()) {
                members.erase(found);
                clear_action();
            }
        }
        m_is_entered_battle = false;
        return;
    }
    if (m__vanished) return;
    yado->changed();
    m__vanished = true;
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(borrowed_character(this));
    if (const auto player = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this))) {
        if (::cw::g_cwpy->m_background && ::cw::g_cwpy->m_background->m_pc_cache.empty()) {
            for (Integer pi = 0; pi < static_cast<Integer>(party->m_members.size()); ++pi)
                ::cw::g_cwpy->m_background->put_pccache(pi);
        }
        if (player->m_inusecardimg && *player->m_inusecardimg) {
            const auto* object = std::get_if<::cw::lib::ObjectPtr>(&(*player->m_inusecardimg)->m_header.storage());
            const auto header = object && *object ? std::dynamic_pointer_cast<::cw::header::CardHeader>(*object) : nullptr;
            if (header) header->set_uselimit(-1, false);
        }
        ::cw::animation::animate_sprite(player, "vanish", true, false, false, arg_battlespeed);
        const auto area_hint = scenario ? scenario->get_versionhint(::cw::g_HINT_AREA) : std::nullopt;
        const bool cancellable = ::cw::g_cwpy->m_sct &&
            (::cw::g_cwpy->m_sct->enable_vanishmembercancellation(scenario_hint) ||
             ::cw::g_cwpy->m_sct->enable_vanishmembercancellation(area_hint));
        if (cancellable) {
            // ネイティブ版の保留処理は、Python版の無条件追加と
            // は異なり、カードごとに一回だけ確定する。 キャンセル・
            // 消去で二重登録すると、二回目の確定でメンバーがすでに消
            // えているため、 そのエラーを隠すのではなく重複を防ぐ。
            if (std::find(party->m_vanished_pcards.begin(), party->m_vanished_pcards.end(), player) == party->m_vanished_pcards.end())
                party->m_vanished_pcards.push_back(player);
        } else {
            commit_vanish();
        }
    } else if (const auto enemy = std::dynamic_pointer_cast<::cw::sprite::card::EnemyCard>(borrowed_character(this))) {
        ::cw::animation::animate_sprite(enemy, "delete", true, false, false, arg_battlespeed);
        commit_vanish();
    } else if (const auto friend_card = std::dynamic_pointer_cast<::cw::sprite::card::FriendCard>(borrowed_character(this))) {
        ::cw::animation::animate_sprite(friend_card, "delete", true, false, false, arg_battlespeed);
        commit_vanish();
    } else {
        throw std::logic_error("set_vanish requires a card character");
    }
    if (card) ::cw::g_cwpy->vanished_card(card);
}

void Character::cancel_vanish()
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("cancel_vanish requires yado party");
    const auto player = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    if (!player) throw std::logic_error("cancel_vanish requires PlayerCard");
    if (!m__vanished) return;
    const auto yado = *::cw::g_cwpy->m_ydata;
    const auto party = *yado->m_party;
    yado->changed();
    if (::cw::sprite::card::is_in_cardgrp(*player))
        throw std::logic_error("cancel_vanish requires card outside card group");
    // Python版と同様、保留一覧の消去は end_scenario に任
    // せる。 呼び出し元がこのベクターを走査し、全PCの復元後に消去する。
    const auto member = std::find_if(party->m_members.begin(), party->m_members.end(), [this](const auto& value) {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
        return object && *object && m_data_typed && std::dynamic_pointer_cast<Tree>(*object) == m_data_typed;
    });
    if (member == party->m_members.end()) throw std::logic_error("cancel_vanish requires party member");
    m__vanished = false;
    Integer index = static_cast<Integer>(std::distance(party->m_members.begin(), member));
    index = std::clamp<Integer>(index, 0, static_cast<Integer>(::cw::g_cwpy->m_pcards.size()));
    // Python版と同様、cwpy.pcards にPlayerCard
    // を公開する前にカードグループの層を復元する。 ALLはUI・ゲー
    // ムの処理間にこれらを参照できるため、同じ途中状態と順序を保つ。
    ::cw::sprite::card::refresh_card_layer(*player);
    // Pythonの list.insert と同様、無条件で挿入する。 重複は
    // 上流の状態エラーなので、C++独自のcontains検査で黙って隠さない。
    ::cw::g_cwpy->m_pcards.insert(::cw::g_cwpy->m_pcards.begin() + index, player);
    // Pythonの cancel_vanish と同様、所属と
    // 層だけを復元する。 カードを表示するか・方法は呼び出し元が
    // 決めるため、非表示・即時復元で二重にアニメーションしない。
}

void Character::commit_vanish()
{
    if (!m__vanished) return;
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("commit_vanish requires yado party");
    const auto yado = *::cw::g_cwpy->m_ydata;
    const auto party = *yado->m_party;
    yado->changed();
    if (const auto player = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this))) {
        const auto return_premium_cards = [&](const auto& pocket) {
            // Python版と同様、tradeが元のポケットからカードを除く
            // ため、ポケットの複製を走査する。 現在のベクターを直接たどると
            // 、最初のプレミアムカードの移動で次のイテレーターが無効になる。
            const auto headers = pocket;
            for (const auto& header : headers) {
                if (header && header->m_premium == "Premium") {
                    ::cw::g_cwpy->trade("BACKPACK", std::nullopt, header, true, nullptr, -1, -1,
                                        false, false, std::nullopt, false, false, true, true, 1);
                }
            }
        };
        return_premium_cards(std::get<0>(m_cardpocket_typed));
        return_premium_cards(std::get<1>(m_cardpocket_typed));
        return_premium_cards(std::get<2>(m_cardpocket_typed));
        if (!player->m_personal_pocket.empty()) {
            for (const auto& header : std::vector<std::shared_ptr<::cw::header::CardHeader>>(player->m_personal_pocket))
                player->remove_personalpocket(header);
            // Python版と同様、個人カードが実際に返った場合だけ整列する。
            party->sort_backpack(std::nullopt, std::nullopt);
        }
        const auto member = std::find_if(party->m_members.begin(), party->m_members.end(), [this](const auto& value) {
            const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
            return object && *object && m_data_typed && std::dynamic_pointer_cast<Tree>(*object) == m_data_typed;
        });
        // Pythonの list.index と同様、キャラクター文書が所属し
        // ていなければ commit_vanish を中止する。 位置0で続ける
        // と無関係なメンバーの画像参照を壊し、パーティの不整合を隠してしまう。
        if (member == party->m_members.end())
            throw std::logic_error("commit_vanish requires party member");
        const auto index = static_cast<Integer>(std::distance(party->m_members.begin(), member));
        for (Integer i = index; i < static_cast<Integer>(party->m_members.size()); ++i) {
            for (const auto& value : ::cw::g_cwpy->update_pcimage(i + 1, false)) {
                const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
                if (!object || !*object) continue;
                if (const auto sprite = std::dynamic_pointer_cast<::cw::sprite::base::CWPySprite>(*object))
                    ::cw::g_cwpy->m_file_updates.insert(sprite);
            }
        }
        if (::cw::g_cwpy->m_background) {
            const auto self_obj = std::static_pointer_cast<::cw::lib::Object>(borrowed_character(this));
            for (const auto& [bgtype, data] : ::cw::g_cwpy->m_background->m_bgs) {
                if (!data) continue;
                const auto* object = std::get_if<::cw::lib::ObjectPtr>(&data->storage());
                const auto cell = object && *object
                    ? std::dynamic_pointer_cast<::cw::sprite::background::BackgroundCellData>(*object) : nullptr;
                if (!cell) continue;
                if (bgtype == ::cw::sprite::background::g_BG_PC) {
                    if (index + 1 <= cell->pcnumber) ::cw::g_cwpy->m_file_updates_bg = true;
                } else if (bgtype == ::cw::sprite::background::g_BG_TEXT) {
                    for (const auto& item : cell->names) {
                        if (!item) continue;
                        const auto* item_object = std::get_if<::cw::lib::ObjectPtr>(&item->m_data.storage());
                        if (item_object && *item_object && *item_object == self_obj) item->m_data = {};
                    }
                }
            }
        }
        party->remove(player);
    }
    lost();
}

void Character::set_enhance_act(::cw::lib::Integer arg_value, ::cw::lib::Integer arg_duration)
{
    mark_yado_changed();
    if (is_unconscious()) { arg_value = 0; arg_duration = 0; }
    if (arg_value == 0) arg_duration = 0;
    if (arg_duration <= 0) arg_value = 0;
    m_enhance_act = std::clamp<::cw::lib::Integer>(arg_value, -10, 10);
    m_enhance_act_dur = std::clamp<::cw::lib::Integer>(arg_duration, 0, 999);
    edit_character_xml(*this, "Property/Enhance/Action", std::to_string(m_enhance_act));
    edit_character_xml(*this, "Property/Enhance/Action", std::to_string(m_enhance_act_dur), std::optional<String>("duration"));
    adjust_beast();
}

