void Character::set_skillpower(::cw::lib::Integer arg_value)
{
    mark_yado_changed();
    for (const auto& header : std::get<0>(m_cardpocket_typed)) if (header) header->set_uselimit(arg_value, false);
    if (::cw::g_cwpy && ::cw::g_cwpy->is_battlestatus() && m_deck) {
        if (arg_value > 0) m_deck->get_skillpower(borrowed_character(this));
        else if (arg_value < 0) m_deck->lose_skillpower(borrowed_character(this), -arg_value);
    }
}

bool Character::set_beast(std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_element, bool arg_vanish, bool arg_is_scenariocard)
{
    bool effected = false;
    if (arg_vanish) {
        const auto beasts = get_pocketcards(::cw::g_POCKET_BEAST);
        for (auto it = beasts.rbegin(); it != beasts.rend(); ++it) {
            if (*it && !(*it)->m_attachment) {
                // Python版と同様、召喚獣の除去効果もイベン
                // トによる破棄とし、手動移動用の確認を抑止する。
                throwaway_card(*it, true, false);
                effected = true;
            }
        }
        return effected;
    }
    if (!arg_element || !*arg_element) throw std::invalid_argument("set_beast requires card XML");
    if (!can_addbeast(*arg_element)) return false;
    auto etree = std::make_shared<Tree>(*arg_element);
    ::cw::content::get_card(etree,
                            ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(borrowed_character(this))),
                            !arg_is_scenariocard, -1, -1, std::nullopt, {}, false, false, false, false,
                            !arg_is_scenariocard, std::nullopt, std::nullopt);
    return true;
}

bool Character::can_addbeast(std::shared_ptr<::cw::data::CWPyElement> arg_carddata)
{
    if (!arg_carddata) return false;
    if (static_cast<Integer>(std::get<2>(m_cardpocket_typed).size()) >= std::get<2>(get_cardpocketspace())) return false;
    return !::cw::header::is_removewithstatus(
        std::move(arg_carddata),
        ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(borrowed_character(this))));
}

void Character::decrease_physical(::cw::lib::String arg_stype, ::cw::lib::Integer arg_time)
{
    for (Integer index = 0; index < arg_time; ++index) {
        const auto uvalue = ::cw::util::div_vocation(get_vocation_val({"vit", "aggressive"})) + m_level + roll_dice(2);
        const auto current = arg_stype == "Poison" ? m_poison : m_paralyze;
        const auto tvalue = current + roll_dice(2);
        bool recover = uvalue >= tvalue;
        const auto dice = roll_dice(2);
        if (dice == 12) recover = true;
        if (dice == 2) recover = false;
        if (recover) {
            if (arg_stype == "Poison") set_poison(-1);
            else set_paralyze(-1);
        }
    }
    adjust_beast();
}

void Character::set_timeelapse(::cw::lib::Integer arg_time, bool arg_fromevent)
{
    if (!is_card_character(*this)) throw std::logic_error("set_timeelapse requires card character");
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_event) throw std::logic_error("set_timeelapse requires event interface");
    mark_yado_changed();
    if (::cw::g_cwpy->m_event->m_in_cardeffectmotion)
        throw std::logic_error("set_timeelapse cannot run during card effect motion");
    if (!arg_fromevent && ::cw::g_cwpy->m_event->m_in_inusecardevent)
        throw std::logic_error("set_timeelapse cannot run during in-use card event");
    count_timedcoupon(-1);
    const bool oldalive = is_alive();
    bool redraw_transition = false;
    bool redraw_status = false;
    const auto shared = borrowed_character(this);
    auto logger = ::cw::g_cwpy->m_advlog;
    auto card = std::dynamic_pointer_cast<::cw::sprite::card::CWPyCard>(shared);
    const auto update_image = [&]() {
        if (card) (void)card->update_image(false, ::cw::g_cwpy->is_runningevent());
    };
    if (is_poison() && !is_unconscious()) {
        decrease_physical("Poison", arg_time);
        if (!is_poison()) {
            if (logger) logger->recover_poison(shared);
            redraw_transition = true;
        } else {
            if (::cw::g_cwpy) ::cw::g_cwpy->play_sound("dump", false, 100, 1, 0, 0, false);
            const auto amount = m_poison;
            const auto dice_count = amount / 5;
            const auto remainder = (amount % 5) * 2;
            Integer damage = roll_dice(dice_count, 10);
            if (remainder) damage += roll_dice(1, remainder);
            const auto oldlife = m_life;
            const auto actual = set_life(-damage);
            if (logger) logger->poison_damage(shared, actual, m_life, oldlife);
            if (card && card->m_status != "reversed" && card->m_status != "hidden")
                ::cw::animation::animate_sprite(card, "lateralvibe", true, false, false, ::cw::g_cwpy->is_battlestatus());
            update_image();
            if (card) ::cw::g_cwpy->add_lazydraw_rect(card->m_rect);
        }
    }
    if (is_paralyze() && !is_petrified() && !is_unconscious()) {
        decrease_physical("Paralyze", arg_time);
        if (!is_paralyze()) {
            if (logger) logger->recover_paralyze(shared);
            redraw_transition = true;
        }
        if (is_analyzable()) redraw_status = true;
    }
    if (is_bind()) {
        set_bind(m_bind - arg_time);
        if (!is_bind()) { if (logger) logger->recover_bind(shared); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (is_silence()) {
        set_silence(m_silence - arg_time);
        if (!is_silence()) { if (logger) logger->recover_silence(shared); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (is_faceup()) {
        set_faceup(m_faceup - arg_time);
        if (!is_faceup()) { if (logger) logger->recover_faceup(shared); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (is_antimagic()) {
        set_antimagic(m_antimagic - arg_time);
        if (!is_antimagic()) { if (logger) logger->recover_antimagic(shared); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (m_mentality_dur > 0) {
        const auto value = m_mentality_dur - arg_time;
        if (value > 0) set_mentality(m_mentality, value);
        else {
            if (logger) logger->recover_mentality(shared, m_mentality);
            set_mentality("Normal", 0);
            redraw_transition = true;
        }
        if (is_analyzable()) redraw_status = true;
    }
    if (m_enhance_act_dur > 0) {
        const auto value = m_enhance_act_dur - arg_time;
        if (value > 0) set_enhance_act(m_enhance_act, value);
        else { if (logger) logger->recover_enhance_act(shared); set_enhance_act(0, 0); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (m_enhance_avo_dur > 0) {
        const auto value = m_enhance_avo_dur - arg_time;
        if (value > 0) set_enhance_avo(m_enhance_avo, value);
        else { if (logger) logger->recover_enhance_avo(shared); set_enhance_avo(0, 0); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (m_enhance_res_dur > 0) {
        const auto value = m_enhance_res_dur - arg_time;
        if (value > 0) set_enhance_res(m_enhance_res, value);
        else { if (logger) logger->recover_enhance_res(shared); set_enhance_res(0, 0); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (m_enhance_def_dur > 0) {
        const auto value = m_enhance_def_dur - arg_time;
        if (value > 0) set_enhance_def(m_enhance_def, value);
        else { if (logger) logger->recover_enhance_def(shared); set_enhance_def(0, 0); redraw_transition = true; }
        if (is_analyzable()) redraw_status = true;
    }
    if (is_unconscious()) set_unconsciousstatus();
    else adjust_beast();
    if ((redraw_transition || redraw_status) && card) {
        // Python版と同様、表示中の状態が失効したら、非表示・再表示の間で一度だけ
        // 再構築する。 それより早く行うと、非表示アニメーションより前になってしまう。
        const bool visible = card->m_status != "reversed" && card->m_status != "hidden";
        if (visible && redraw_transition) {
            ::cw::animation::animate_sprite(card, "hide", true, false, false, ::cw::g_cwpy->is_battlestatus());
            update_image();
            ::cw::animation::animate_sprite(card, "deal", true, false, false, ::cw::g_cwpy->is_battlestatus());
        } else {
            update_image();
        }
        ::cw::g_cwpy->add_lazydraw(std::static_pointer_cast<::cw::lib::Object>(card));
    }
    if (oldalive && is_dead() && (dynamic_cast<Player*>(this) || dynamic_cast<Enemy*>(this))) {
        std::shared_ptr<::cw::event::EventEngine> events;
        const auto scenario = std::dynamic_pointer_cast<::cw::data::ScenarioData>(current_system_data());
        if (dynamic_cast<Player*>(this)) {
            if (scenario && scenario->m_playerevents) events = *scenario->m_playerevents;
        } else if (const auto enemy = std::dynamic_pointer_cast<::cw::sprite::card::EnemyCard>(shared)) {
            events = enemy->m_events;
        }
        if (events) {
            std::shared_ptr<Character> previous_target;
            if (arg_fromevent) {
                const auto remember = [&previous_target](const auto& cards) {
                    for (const auto& candidate : cards) {
                        if (!previous_target && candidate && candidate->_has_coupon("＠イベント対象"))
                            previous_target = std::static_pointer_cast<Character>(candidate);
                    }
                };
                remember(::cw::g_cwpy->get_pcards({}));
                remember(::cw::g_cwpy->get_ecards({}));
                remember(::cw::g_cwpy->get_fcards({}));
                if (previous_target) previous_target->_remove_coupon("＠イベント対象", true);
            }
            try {
                if (scenario && scenario->is_wsnversion("2", std::nullopt))
                    _set_coupon("＠イベント対象", 0, true);
                if (arg_fromevent) {
                    if (const auto death = events->check_keynum(1); death && *death)
                        (*death)->run_scenarioevent(false);
                } else {
                    events->start(1, std::nullopt, false, false);
                }
            } catch (...) {
                _remove_coupon("＠イベント対象", true);
                if (previous_target) previous_target->_set_coupon("＠イベント対象", 0, true);
                throw;
            }
            _remove_coupon("＠イベント対象", true);
            if (previous_target) previous_target->_set_coupon("＠イベント対象", 0, true);
        }
    }
}

void Character::set_hold_all(::cw::lib::Integer arg_pocket, bool arg_value)
{
    // 変更前に検証する。Python版は先に hold_all を参照するため、 負の
    // ポケット値が後の種類のassertより前に最後のフィールドを変える場合がある。
    if (arg_pocket < 0 || arg_pocket >= static_cast<Integer>(m_hold_all.size()))
        throw std::out_of_range("set_hold_all pocket index");
    m_hold_all[static_cast<std::size_t>(arg_pocket)] = arg_value;
    const String path = arg_pocket == ::cw::g_POCKET_SKILL ? "SkillCards" :
                      (arg_pocket == ::cw::g_POCKET_ITEM ? "ItemCards" :
                       (arg_pocket == ::cw::g_POCKET_BEAST ? "BeastCards" : ""));
    if (path.empty()) throw std::out_of_range("set_hold_all pocket index");
    edit_character_xml(*this, path, arg_value ? "True" : "False", std::optional<String>("hold_all"));
}

