bool Player::add_personalpocket(std::shared_ptr<::cw::header::CardHeader> arg_header, ::cw::lib::Integer arg_index)
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _add_personalpocket(std::move(arg_header), arg_index);
}

bool Player::_add_personalpocket(std::shared_ptr<::cw::header::CardHeader> arg_header, ::cw::lib::Integer arg_index)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("add_personalpocket requires yado party");
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    const auto unassigned_index = [](const auto& value) {
        const auto* integer = std::get_if<Integer>(&value.storage());
        return integer && *integer == -1;
    };
    const bool index_unassigned = arg_header &&
        unassigned_index(std::get<0>(arg_header->m_personal_owner_index)) &&
        unassigned_index(std::get<1>(arg_header->m_personal_owner_index));
    if (!card || !arg_header || !arg_header->is_backpackheader() ||
        !arg_header->m_personal_owner.expired() || !index_unassigned ||
        std::find(m_personal_pocket.begin(), m_personal_pocket.end(), arg_header) != m_personal_pocket.end())
        throw std::logic_error("add_personalpocket requires an unowned backpack card");
    if (!m_data_typed || !m_data_typed->getroot())
        throw std::logic_error("add_personalpocket requires adventurer XML");
    if (static_cast<Integer>(m_personal_pocket.size()) >= _get_personalpocketspace()) return false;
    arg_header->m_personal_owner = card;
    const auto size = static_cast<Integer>(m_personal_pocket.size());
    if (arg_index == -1) {
        arg_index = size;
        m_personal_pocket.push_back(arg_header);
    } else {
        // Pythonの list.insert と同様、任意の負・上限超過の位置を受け付ける。
        arg_index = arg_index < 0 ? std::max<Integer>(0, size + arg_index)
                                  : std::min<Integer>(size, arg_index);
        m_personal_pocket.insert(m_personal_pocket.begin() + arg_index, arg_header);
    }
    update_personalownerindex(-1);
    if (m_data_typed) {
        auto personal = m_data_typed->find("PersonalCards");
        if (!personal || !*personal) {
            auto created = ::cw::data::make_element("PersonalCards");
            m_data_typed->append(".", created);
            personal = m_data_typed->find("PersonalCards");
        }
        if (personal && *personal) {
            String path = path_basename(arg_header->m_fpath);
            auto element = ::cw::data::make_element("PersonalCard", path);
            if (arg_index >= static_cast<Integer>((*personal)->m_children.size())) (*personal)->append(element);
            else (*personal)->insert(arg_index, element);
        }
    }
    mark_edited(*this);
    return true;
}

void Player::remove_personalpocket(std::shared_ptr<::cw::header::CardHeader> arg_header)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("remove_personalpocket requires yado party");
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    const auto assigned_index = [](const auto& value) {
        const auto* integer = std::get_if<Integer>(&value.storage());
        return !integer || *integer != -1;
    };
    const bool index_assigned = arg_header &&
        (assigned_index(std::get<0>(arg_header->m_personal_owner_index)) ||
         assigned_index(std::get<1>(arg_header->m_personal_owner_index)));
    if (!card || !arg_header || !arg_header->is_backpackheader() ||
        arg_header->m_personal_owner.lock() != card || !index_assigned)
        throw std::logic_error("remove_personalpocket requires an owned backpack card");
    const auto found = std::find(m_personal_pocket.begin(), m_personal_pocket.end(), arg_header);
    if (found == m_personal_pocket.end())
        throw std::logic_error("remove_personalpocket requires personal pocket membership");
    const auto index = static_cast<Integer>(std::distance(m_personal_pocket.begin(), found));
    if (!m_data_typed)
        throw std::logic_error("remove_personalpocket requires adventurer XML");
    const auto personal = m_data_typed->find("PersonalCards");
    if (!personal || !*personal || index >= static_cast<Integer>((*personal)->m_children.size()))
        throw std::logic_error("remove_personalpocket requires matching PersonalCards XML");
    arg_header->m_personal_owner.reset();
    arg_header->m_personal_owner_index = {::cw::lib::Value(-1), ::cw::lib::Value(-1)};
    m_personal_pocket.erase(found);
    if (::cw::g_cwpy && card && ::cw::g_cwpy->m_card_takenouttemporarily_personal_owner &&
        *::cw::g_cwpy->m_card_takenouttemporarily_personal_owner == card) {
        Integer personal_index = 0;
        if (const auto* n = std::get_if<Integer>(&::cw::g_cwpy->m_card_takenouttemporarily_personal_index.storage()))
            personal_index = *n;
        if (index < personal_index)
            ::cw::g_cwpy->m_card_takenouttemporarily_personal_index = ::cw::lib::Value(personal_index - 1);
    }
    (*personal)->remove((*personal)->m_children[static_cast<std::size_t>(index)]);
    if ((*personal)->m_children.empty()) {
        const auto root = m_data_typed->getroot();
        if (!root) throw std::logic_error("remove_personalpocket requires adventurer XML root");
        root->remove(*personal);
    }
    update_personalownerindex(-1);
    mark_edited(*this);
}

void Player::store_personalpocket()
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("store_personalpocket requires yado party");
    if (m_personal_pocket.empty()) return;
    const auto yado = *::cw::g_cwpy->m_ydata;
    auto headers = m_personal_pocket;
    std::reverse(headers.begin(), headers.end());
    for (const auto& header : headers) {
        if (!header) throw std::logic_error("store_personalpocket contains a null card");
        add_cardpocketmemory(header, true);
        ::cw::g_cwpy->trade("STOREHOUSE", std::nullopt, header, true, nullptr, -1, -1,
                            false, false, std::nullopt, false, false, true, true, 1);
    }
    // Python版と同様、各交換で対応するXML項目が除かれたことを要求する
    // 。 一覧が残る場合は、カード置場への移動が片側だけを変更したことを示す。
    if (!m_data_typed || m_data_typed->find("PersonalCards"))
        throw std::logic_error("store_personalpocket did not clear PersonalCards XML");
    yado->sort_storehouse(std::nullopt);
}

void Player::restore_personalpocket(bool arg_sort)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("restore_personalpocket requires yado party");
    const auto yado = *::cw::g_cwpy->m_ydata;
    // Python版と同様、ここではカード置場の複製を渡す。 公開APIは入力
    // 一覧を変更するが、この呼び出し元の検索候補はスナップショットとして扱う。
    auto candidates = yado->m_storehouse;
    revert_personalpocket(candidates, false);
    if (arg_sort) (*yado->m_party)->sort_backpack(std::nullopt, std::nullopt);
}

void Player::refresh_personalpocket(std::map<::cw::lib::String, std::shared_ptr<::cw::header::CardHeader>>& arg_personalcard_tbl)
{
    // Python版と同様、呼び出し元の空の辞書へデータを入れ、 後続のPCが、パーテ
    // ィの荷物袋から作った同じファイル名とヘッダーの対応表を再利用できるようにする。
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    if (!card) throw std::logic_error("refresh_personalpocket requires PlayerCard");
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("refresh_personalpocket requires yado party");
    // Python版と同様、ここではPlayerCard側の一覧だ
    // けを組み直す。 読み込みを整理・保存操作に変えず、所有関係
    // は下の正式なPersonalCards項目から設定し直す。
    m_personal_pocket.clear();
    if (!m_data_typed) throw std::logic_error("refresh_personalpocket requires adventurer XML");
    const auto personal = m_data_typed->find("PersonalCards");
    if (!personal || !*personal) return;
    if (arg_personalcard_tbl.empty()) {
        for (const auto& header : (*::cw::g_cwpy->m_ydata)->m_party.value()->m_backpack) {
            if (!header) continue;
            arg_personalcard_tbl[path_basename(header->m_fpath)] = header;
        }
    }
    for (const auto& element : std::vector<std::shared_ptr<Element>>((*personal)->m_children)) {
        if (!element || element->m_tag != "PersonalCard") throw std::logic_error("PersonalCards contains non-PersonalCard");
        const auto found = arg_personalcard_tbl.find(element->m_text);
        if (found == arg_personalcard_tbl.end() || !found->second) {
            (*personal)->remove(element);
            continue;
        }
        found->second->m_personal_owner = card;
        m_personal_pocket.push_back(found->second);
    }
    update_personalownerindex(-1);
}

::cw::lib::Integer Player::get_personalpocketspace()
{
    std::lock_guard<std::mutex> coupon_guard(g__couponlock);
    return _get_personalpocketspace();
}

::cw::lib::Integer Player::_get_personalpocketspace()
{
    Integer level = m_level;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting && !::cw::g_cwpy->m_setting->m_level_adjustment_affect_personal_pocket)
        level = _get_limitlevel();
    const auto capacity = level / 2 + level % 2 + 2;
    const auto level_capacity = std::clamp<Integer>(capacity, 1, 10);
    return has_expanded_pc_card_limits()
        ? configured_pc_capacity("pcPersonalLimit", level_capacity) : level_capacity;
}

void Player::replace_personalcardposition(std::shared_ptr<::cw::header::CardHeader> arg_header1, std::shared_ptr<::cw::header::CardHeader> arg_header2)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party)
        throw std::logic_error("replace_personalcardposition requires yado party");
    if (!arg_header1 || !arg_header2) throw std::invalid_argument("replace_personalcardposition requires headers");
    const auto found1 = std::find(m_personal_pocket.begin(), m_personal_pocket.end(), arg_header1);
    const auto found2 = std::find(m_personal_pocket.begin(), m_personal_pocket.end(), arg_header2);
    if (found1 == m_personal_pocket.end() || found2 == m_personal_pocket.end()) throw std::out_of_range("personal card not found");
    const auto index1 = static_cast<Integer>(std::distance(m_personal_pocket.begin(), found1));
    const auto index2 = static_cast<Integer>(std::distance(m_personal_pocket.begin(), found2));
    std::swap(m_personal_pocket[static_cast<std::size_t>(index1)], m_personal_pocket[static_cast<std::size_t>(index2)]);
    if (!m_data_typed) return;
    const auto personal = m_data_typed->find("PersonalCards");
    // Python版と同様、メモリ内の交換後、XML一覧が
    // なければ直ちに戻る。 存在する場合は短い・壊れた一覧
    // の参照エラーを伝え、所有関係だけを黙って更新しない。
    if (!personal || !*personal) return;
    if (index1 >= static_cast<Integer>((*personal)->m_children.size()) ||
        index2 >= static_cast<Integer>((*personal)->m_children.size()))
        throw std::out_of_range("PersonalCards XML does not match personal pocket");
    std::swap((*personal)->m_children[static_cast<std::size_t>(index1)],
              (*personal)->m_children[static_cast<std::size_t>(index2)]);
    update_personalownerindex(index1);
    update_personalownerindex(index2);
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata && (*::cw::g_cwpy->m_ydata)->m_party)
        (*(*::cw::g_cwpy->m_ydata)->m_party)->sort_backpack(std::nullopt, std::nullopt);
    mark_edited(*this);
}

void Player::update_personalownerindex(::cw::lib::Integer arg_index)
{
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    if (!card) throw std::logic_error("update_personalownerindex requires PlayerCard");
    const auto update_one = [&card, this](Integer index, Integer owner_index) {
        const auto& header = m_personal_pocket[static_cast<std::size_t>(index)];
        if (!header) throw std::logic_error("personal pocket contains a null card");
        header->m_personal_owner_index = {
            ::cw::lib::Value(card->m_index_typed), ::cw::lib::Value(owner_index)};
    };
    if (arg_index != -1) {
        const auto size = static_cast<Integer>(m_personal_pocket.size());
        auto index = arg_index;
        if (index < 0) index += size;
        if (index < 0 || index >= size)
            throw std::out_of_range("personal card index is out of range");
        update_one(index, arg_index);
        return;
    }
    for (Integer index = 0; index < static_cast<Integer>(m_personal_pocket.size()); ++index)
        update_one(index, index);
}

void Player::lost()
{
    const auto card = std::dynamic_pointer_cast<::cw::sprite::card::PlayerCard>(borrowed_character(this));
    if (!card) throw std::logic_error("Player::lost requires PlayerCard");
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata)
        throw std::logic_error("Player::lost requires yado data");
    mark_yado_changed();
    remove_numbercoupon();
    remove_timedcoupons(false);
    edit_character_xml(*this, "Property", "True", std::optional<String>("lost"));
    // Python版と同様、ここでは別のパス検査をせず、XMLを編集・書き込みする。
    if (m_data_typed) m_data_typed->write_xml(false);
    const auto yado = *::cw::g_cwpy->m_ydata;
    if (yado->m_losted_sdata && *yado->m_losted_sdata) {
        const auto lost_path = ::cw::util::get_yado_relpath(
            m_data_typed ? m_data_typed->m_fpath : String{}, yado->m_yadodir, yado->m_tempdir);
        (*yado->m_losted_sdata)->m_lostadventurers.insert(lost_path);
    } else if (::cw::g_cwpy->is_playingscenario()) {
        const auto system = current_system_data();
        const auto scenario = system ? std::dynamic_pointer_cast<::cw::data::ScenarioData>(system) : nullptr;
        if (!scenario) throw std::logic_error("Player::lost requires active scenario data");
        const auto lost_path = ::cw::util::get_yado_relpath(
            m_data_typed ? m_data_typed->m_fpath : String{}, yado->m_yadodir, yado->m_tempdir);
        scenario->m_lostadventurers.insert(lost_path);
    }
    // Python版と同様、まだcardgrpにある場合だけ表
    // 示・一覧から除く。 commit_vanish は代理の
    // 項目を削除済みなので、再び隠して表示状態を二度消さない。
    if (::cw::sprite::card::is_in_cardgrp(*card)) {
        card->hide();
        ::cw::sprite::card::remove_from_cardgrp(*card);
        auto& pcards = ::cw::g_cwpy->m_pcards;
        const auto found = std::find(pcards.begin(), pcards.end(), card);
        if (found == pcards.end())
            throw std::logic_error("Player::lost card group/member list mismatch");
        pcards.erase(found);
    }
}

void Player::set_name(::cw::lib::String arg_name)
{
    Character::set_name(arg_name);
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata) {
        const auto yado = *::cw::g_cwpy->m_ydata;
        if (yado) for (const auto& header : yado->m_partyrecord)
            // 型付きXMLツリーが、ネイティブのPlayerデータを所有する。 そのファイル
            // パスはPythonの self.data.fpath と同じパーティ記録のメ
            // ンバーを識別する。 未初期化のネイティブツリーでは、空パスを未設定値にする。
            if (header) header->rename_member(m_data_typed ? m_data_typed->m_fpath : String{}, arg_name);
    }
    if (::cw::g_cwpy) {
        if (::cw::g_cwpy->m_background)
            ::cw::g_cwpy->m_background->reload(false, {"Default", ::cw::lib::Value("Default")},
                                                true, {}, {}, {}, false, true);
        ::cw::g_cwpy->update_mcardnames();
    }
}

// Python版と同様、Character/Playerの公開称号APIで一つの再入不可のロッ
// クを共有する。 内部のアンダースコア付きAPIと has_coupon_nolock は、呼
// び出し元がそのロックを持つか、 Python版と同じゲームスレッド専用経路を使う前提。 RAII
// により、synclockのfinallyと同じく全戻り・例外でミューテックスを解放する。
std::mutex g__couponlock;

bool Character_find_keycode_match(::cw::lib::String arg_keycode, std::vector<::cw::lib::String> arg_keycodes)
{
    return std::find(arg_keycodes.begin(), arg_keycodes.end(), arg_keycode) != arg_keycodes.end();
}

::cw::lib::Value Character_get_enhance_def_lambda_line_1864(::cw::lib::Value arg_a, ::cw::lib::Value arg_b)
{
    const auto lhs = value_decimal(arg_a);
    const auto rhs = value_decimal(arg_b);
    if (!lhs || !rhs) return {};
    try {
        // 計算・能力補正の積はDecimalのまま保つ。 Real
        // 入力の変換は、上のネイティブ互換境界だけで行う。
        return ::cw::lib::Value(*lhs * *rhs);
    } catch (const ::cw::lib::DecimalError&) {
        return {};
    }
}

::cw::lib::Value Character_get_enhance_def_lambda_line_1867(::cw::lib::Value arg_a, ::cw::lib::Value arg_b)
{
    return Character_get_enhance_def_lambda_line_1864(std::move(arg_a), std::move(arg_b));
}

::cw::lib::Integer Character__get_enhance_impl_wrap_enhval(::cw::lib::Integer arg_val, ::cw::lib::Integer arg_orig_val)
{
    if (arg_orig_val < 0) return std::clamp<::cw::lib::Integer>(arg_val, -10, -1);
    if (arg_orig_val > 0) return std::clamp<::cw::lib::Integer>(arg_val, 1, 10);
    return 0;
}

::cw::lib::Integer calc_maxlife(::cw::lib::Real arg_vit, ::cw::lib::Real arg_minval, ::cw::lib::Integer arg_level)
{
    arg_vit = std::max<::cw::lib::Real>(arg_vit, 1.0);
    arg_minval = std::max<::cw::lib::Real>(arg_minval, 1.0);
    arg_level = std::max<::cw::lib::Integer>(arg_level, 1);
    // Python版は level + 1 を上限のない整数で計算する。 極端な取り込
    // みレベルでもIntegerの加算を先にあふれさせないよう、変換してから加える。
    const Real result = (arg_vit / 2.0 + 4.0) *
                        (static_cast<Real>(arg_level) + 1.0) +
                        arg_minval / 2.0;
    return real_to_integer(result).value_or(std::numeric_limits<::cw::lib::Integer>::max());
}

::cw::lib::Real calc_lifecoefficient(std::shared_ptr<::cw::data::CWPyElementTree> arg_data, ::cw::lib::Integer arg_level, ::cw::lib::Integer arg_maxlife, ::cw::lib::Integer arg_vit, ::cw::lib::Integer arg_minval)
{
    auto coeff = arg_data ? arg_data->getfloat("Property/Life", ::cw::lib::Value("coefficient"), 0.0) : 0.0;
    if (coeff <= 0.0) {
        const auto maxlife2 = calc_maxlife(arg_vit, arg_minval, arg_level);
        if (maxlife2 == arg_maxlife) {
            coeff = 1.0;
        } else {
            coeff = static_cast<Real>(arg_maxlife) / static_cast<Real>(maxlife2);
            if (arg_data) {
                arg_data->edit("Property/Life", ::cw::lib::python_float_repr(coeff), std::optional<String>("coefficient"));
                arg_data->m_is_edited = true;
            }
        }
    }
    return coeff;
}

